comms.text:
@1 חֲזֵי דִי אֲנָא יָהֵב קֳדָמֵיכוֹן יוֹמָא דֵין בִּרְכָן וּלְוָטִין:
@2 יָת בִּרְכָן דִי תְקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֳלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין:
@3 וּלְוָטִין אִם לָא תְקַבְּלוּן לְפִקוּדַיָא דַיְיָ אֱלָהֲכוֹן וְתִסְטוּן מִן אָרְחָא דִי אֲנָא מְפַקֵד יָתְכוֹן יוֹמָא דֵין לִמְהַךְ בָּתַר טַעֲוַת עַמְמַיָא דִי לָא יְדַעְתּוּן:
@4 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל תַּמָן לְמֵירְתַהּ וְתִתֵּן יָת מְבָרְכַיָא עַל טוּרָא דִגְרִזִין וְיָת מְלַטְטַיָא עַל טוּרָא דְעֵיבָל:
@5 הֲלָא אִנוּן בְּעִבְרָא דְיַרְדְנָא אֲחוֹרֵי אֹרַח מַעֲלָנֵי שִׁמְשָׁא בְּאַרְעָא כְּנַעְנָאָה דְיָתֵב בְּמֵישְׁרָא לָקֳבֵל גִלְגְלָא בִּסְטַר מֵישְׁרֵי מֹרֶה:
@6 אֲרֵי אַתּוּן עָבְרִין יָת יַרְדְנָא לְמֵעַל לְמֵירַת יָת אַרְעָא דַיְיָ אֱלָהֲכוֹן יָהֵב לְכוֹן וְתֵירְתוּן יָתַהּ וְתֵיתְבוּן בַּהּ:
@7 וְתִטְרוּן לְמֶעְבַּד יָת כָּל קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא יָהֵב קֳדָמֵיכוֹן יוֹמָא דֵין:
@8 אִלֵין קְיָמַיָא וְדִינַיָא דִי תִטְרוּן לְמֶעְבַּד בְּאַרְעָא דִיהַב יְיָ אֱלָהָא דַאֲבְהָתָךְ לָךְ לְמֵירְתַהּ כָּל יוֹמַיָא דִי אַתּוּן קַיָמִין עַל אַרְעָא:
@9 אַבָּדָא תְאַבְּדוּן יָת כָּל אַתְרַיָא דִי פְלָחוּ תַמָן עַמְמַיָא דִי אַתּוּן יָרְתִין יָתְהוֹן יָת טַעֲוָתְהוֹן עַל טוּרַיָא רָמַיָא וְעַל רָמָתָא וּתְחוֹת כָּל אִילַן עַבּוֹף:
@10 וּתְתָרְעוּן יָת אֱגוֹרֵיהוֹן וּתְתַבְּרוּן יָת קָמָתְהוֹן וַאֲשֵׁרֵיהוֹן תּוֹקְדוּן בְּנוּרָא וְצַלְמֵי טַעֲוָתְהוֹן תְּקוֹצְצוּן וְתוֹבְדוּן יָת שִׁמְהוֹן מִן אַ:תרָא הַהוּא:
@11 לָא תַעְבְּדוּן כֵּן קֳדָם יְיָ אֱלָהָכוֹן:
@12 אֱלָהֵן לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהֲכוֹן מִכָּל שִׁבְטֵּיכוֹן לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן לְבֵית שְׁכִנְתֵּהּ תִּתְבְּעוּן וְתֵיתוּן לְתַמָן:
@13 וְתַיְתוּן לְתַמָן עֲלָוָתֵיכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן וְיָת מַעְשְׂרָתֵיכוֹן וְיָת אַפְרָשׁוּת יֶדְכוֹן וְנִדְרֵיכוֹן וְנִדְבָתֵיכוֹן וּבְכוֹרֵי תוֹרְכוֹן וְעָנְכוֹן:
@14 וְתֵיכְלוּן תַּמָן קֳדָם יְיָ אֱלָהֲכוֹן וְתֶחֱדוּן בְכֹל אוֹשָׁטוּת יֶדְכוֹן אַתּוּן וֶאֱנַשׁ בָּתֵּיכוֹן דִי בָרְכָךְ יְיָ אֱלָהָךְ:
@15 לָא תַעְבְּדוּן כְּכֹל דִי אֲנַחְנָא עָבְדִין הָכָא יוֹמָא דֵין גְבַר כָּל מָן דְכָשַׁר קֳדָמוֹהִי:
@16 אֲרֵי לָא אֲתֵיתוּן עַד כְּעָן לְבֵית נְיָחָא וּלְאַחֲסָנָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@17 וְתַעְבְּרוּן יָת יַרְדְנָא וְתֵיתְבוּן בְּאַרְעָא דַיְיָ אֱלָהֲכוֹן מַחְסֵן יָתְכוֹן וִינִיחַ לְכוֹן מִכָּל בַּעֲלֵי דְבָבֵיכוֹן מִסְחוֹר סְחוֹר וְתֵיתְבוּן לְרָחְצָן:
@18 וִיהֵי אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהֲכוֹן בֵּהּ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן לְתַמָן תַּיְתוּן יָת כָּל דִי אֲנָא מְפַקֵד יָתְכוֹן עֲלָוָתֵיכוֹן וְנִכְסַת קוּדְשֵׁיכוֹן מַעְשְׂרָתֵיכוֹן וְאַפְרָשׁוּת יֶדְכוֹן וְכֹל שְׁפַר נִדְרֵיכוֹן דִי תִדְרוּן קֳדָם יְיָ:
@19 וְתֶחֱדוּן קֳדָם יְיָ אֱלָהֲכוֹן אַתּוּן וּבְנֵיכוֹן וּבְנָתֵיכוֹן וְעַבְדֵיכוֹן וְאַמְהָתֵיכוֹן וְלֵוָאָה דִי בְקִרְוֵיכוֹן אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמְכוֹן:
@20 אִסְתַּמַר לָךְ דִילְמָא תַסֵק עֲלָוָתָךְ בְּכָל אַתְרָא דִי תֶחֱזֵי:
@21 אֶלָהֵן בְּאַתְרָא דִי יִתִּרְעֵי יְיָ בְּחַד מִן שִׁבְטָיךְ תַּמָן תַּסֵק עֲלָוָתָךְ וְתַמָן תַּעְבֵּד כֹּל דִי אֲנָא מְפַקְדָךְ:
@22 לְחוֹד בְּכָל רְעוּת נַפְשָׁךְ תִּכּוֹס וְתֵיכוּל בִּשְׂרָא כְּבִרְכְּתָא דַיְיָ אֱלָהָךְ דִי יְהַב לָךְ בְּכָל קִרְוָיךְ מְסָאָבָא וְדַכְיָא יֵכְלֻנֵהּ כִּבְשַׂר טַבְיָא וְאַיְלָא:
@23 לְחוֹד דְמָא לָא תֵיכְלוּן עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@24 לֵית לָךְ רְשׁוּ לְמֵיכַל בְּקִרְוָיךְ מַעְשַׂר עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וּבְכוֹרֵי תוֹרָךְ וְעָנָךְ וְכָל נִדְרָךְ דִי תִדַר וְנִדְבָתָיךְ וְאַפְרָשׁוּת יְדָךְ:
@25 אֱלָהֵן קֳדָם יְיָ אֱלָהָךְ תֵּיכְלִנֵהּ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה דִי בְקִרְוָיךְ וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ בְּכָל אוֹשָׁטּוּת יְדָךְ:
@26 אִסְתַּמַר לָךְ דִילְמָא תִשְׁבּוֹק יָת לֵוָאֵי כָּל יוֹמָיךְ עַל אַרְעָךְ:
@27 אֲרֵי יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי מַלִיל לָךְ וְתֵימַר אֵיכוּל בִּשְׂרָא אֲרֵי תִתִּרְעֵי נַפְשָׁךְ לְמֵיכַל בִּשְׂרָא בְּכָל רְעוּת נַפְשָׁךְ תֵּיכוּל בִּשְׂרָא:
@28 אֲרֵי יִתְרָחַק מִנָךְ אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן וְתִכּוֹס מִתּוֹרָךְ וּמֵעָנָךְ דִי יְהַב יְיָ לָךְ כְּמָא דִי פַּקֵדִתָּךְ וְתֵיכוּל בְּקִרְוָיךְ בְּכֹל רְעוּת נַפְשָׁךְ:
@29 בְּרַם כְּמָא דִי מִתְאֲכֵל בְּשַׂר טַבְיָא וְאַיְלָא כֵּן תֵּיכְלִנֵהּ מְסָאָבָא וְדַכְיָא כַּחֲדָא יֵכְלִנֵהּ:
@30 לְחוֹד תְּקֵף בְּדִיל דְלָא לְמֵיכַל דְּמָא אֲרֵי דְמָא הוּא נַפְשָׁא וְלָא תֵיכוּל נַפְשָׁא עִם בִּשְׂרָא:
@31 לָא תֵּיכְלִנֵהּ עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@32 לָא תֵּיכְלִנֵהּ בְּדִיל דְיֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ אֲרֵי תַעְבֵּד דְכָשָׁר קֳדָם יְיָ:
@33 לְחוֹד מַעְשַׂר קוּדְשָׁיךְ דִיהוֹן לָךְ וְנִדְרָךְ תִּטוֹל וְתֵיתֵי לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@34 וְתַעְבֵּד עֲלָוָתָךְ בִּשְׂרָא וּדְמָא עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וְדַם נִכְסַת קוּדְשָׁיךְ יִתָּשַׁד עַל מַדְבְּחָא דַיְיָ אֱלָהָךְ וּבִשְׂרָא תֵּיכוּל:
@35 טַר וּתְקַבֵּל יָת כָּל פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ בְּדִיל דְיֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ עַד עֳלָם אֲרֵי תַעְבֵּד דְתָקֵן וּדְכָשַׁר קֳדָם יְיָ אֱלָהָךְ:
@36 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי אַתְּ עָלֵל לְתַמָן לְתָרָכָא יָתְהוֹן מִקֳדָמָךְ וְתֵירַת יָתְהוֹן וְתֵיתַב בְּאַרְעֲהוֹן:
@37 אִסְתַּמַר לָךְ דִילְמָא תִתָּקַל בַּתְרֵיהוֹן בָּתַר דְיִשְׁתֵּצוּן מִקֳדָמָךְ וְדִילְמָא תִתְבַּע לְטַעֲוָתְהוֹן לְמֵימַר אֶכְדֵין פָּלְחִין עַמְמַיָא הָאִלֵין יָת טַעֲוָתְהוֹן וְאֶעְבֵּד כֵּן אַף אֲנָא:
@38 לָא תַעְבֵּד כֵּן קֳדָם יְיָ אֱלָהָךְ אֲרֵי כָּל דִמְרָחָק קֳדָם יְיָ דִי סָנֵי עֲבָדוּ לְטַעֲוָתְהוֹן אֲרֵי אַף יָת בְּנֵיהוֹן וְיָת בְּנָתֵיהוֹן מוֹקְדִין בְּנוּרָא לְטַּעֲוָתְהוֹן:
@39 יָת כָּל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן יָתֵהּ תִּטְרוּן לְמֶעְבָּד לָא תוֹסְפוּן עֲלוֹהִי וְלָא תִמְנְעוּן מִנֵהּ:
@40 אֲרֵי יְקוּם בֵּינָךְ נְבִיָא אוֹ חָלֵם חֶלְמָא וְיִתֶּן לָךְ אָת אוֹ מוֹפְתָא:
@41 וְיֵיתֵי אָתָא וּמוֹפְתָא דִי מַלִיל עִמָךְ לְמֵימָר נְהַךְ בָּתַר טַעֲוַת עַמְמַיָא דִי לָא יְדַעְתָּנוּן וְנִפְלְחִנוּן:
@42 לָא תְקַבֵּל לְפִתְגָמֵי נְבִיָא הַהוּא אוֹ לְחָלֵם חֶלְמָא הַהוּא אֲרֵי מְנַסֵי יְיָ אֱלָהֲכוֹן יָתְכוֹן לְמִדַע הַאִיתֵיכוֹן רָחֲמִין יָת יְיָ אֱלָהֲכוֹן בְכָל לִבְּכוֹן וּבְכָל נַפְשְׁכוֹן:
@43 בָּתַר דַחַלְתָּא דַיְיָ אֱלָהֲכוֹן תְהָכוּן וְיָתֵהּ תִּדְחֲלוּן וְיָת פִּקוּדוֹהִי תִטְּרוּן וּלְמֵימְרֵהּ תְּקַבְּלוּן וְקָדָמוֹהִי תִפְלְחוּן וּבְדַחַלְתֵּהּ תִּתְקָרְבוּן:
@44 וּנְבִיָא הַהוּא אוֹ חָלֵם חֶלְמָא הַהוּא יִתְקְטֵּל אֲרֵי מַלִיל סַטְיָא עַל יְיָ אֱלָהֲכוֹן דִי אַפֵּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם וּדְפָרְקָךְ מִבֵּית עַבְדוּתָא לְאַטְעֲיוּתָךְ מִן אָרְחָא דִי פַקְדָךְ יְיָ אֱלָהָךְ לִמְהַךְ בַּהּ וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@45 אֲרֵי יְמַלְכִנָךְ אֲחוּךְ בַּר אִמָךְ אוֹ בְרָךְ אוֹ בְרַתָּךְ אוֹ אִתַּת קְיָמָךְ אוֹ חַבְרָךְ דִי כְנַפְשָׁךְ בְּסִתְרָא לְמֵימַר נְהַךְ וְנִפְלַח לְטַעֲוַת עַמְמַיָא דִי לָא יְדַעְתְּ אַתְּ וַאֲבָהָתָךְ:
@46 מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן דִקְרִיבִין לָךְ אוֹ דִרְחִיקִין מִנָךְ מִסְיָפֵי אַרְעָא וְעַד סְיָפֵי אַרְעָא:
@47 לָא תֵיבֵי לֵהּ וְלָא תְקַבֵּל מִנֵהּ וְלָא תְחוּס עֵינָךְ עֲלוֹהִי וְלָא תְרַחַם וְלָא תְכַסֵי עֲלוֹהִי:
@48 אֲרֵי מִקְטַל תִּקְטְּלִנֵהּ יְדָךְ תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְבַתְרֵיתָא:
@49 וְתִרְגְמִנֵהּ בְּאַבְנַיָא וִימוּת אֲרֵי בָעָא לְאַטְעֲיוּתָךְ מִדַחַלְתָּא דַיְיָ אֱלָהָךְ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@50 וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@51 אֲרֵי תִשְׁמַע בְּחַד מִקִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמִתַּב תַּמָן לְמֵימָר:
@52 נְפָקוּ גֻבְרִין בְּנֵי רִשְׁעָא מִבֵּינָךְ וְאַטְעָיוּ יָת יָתְבֵי קַרְתְּהוֹן לְמֵימָר נְהַךְ וְנִפְלַח לְטַעֲוַת עַמְמַיָא דִי לָא יְדַעְתּוּן:
@53 וְתִתְבַּע וְתִבְדוֹק וְתִשְׁאַל יָאוּת וְהָא קֻשְׁטָּא כֵּוַן פִּתְגָמָא אִתְעֲבִידָא תּוֹעֶבְתָּא הָדָא בֵּינָךְ:
@54 מִמְחָא תִמְחֵי יָת יָתְבֵי קַרְתָּא הַהִיא לְפִתְגַם דְחָרֶב גַמַר יָתַהּ וְיָת כָּל דִי בַהּ וְיָת בְּעִירַהּ לְפִתְגַם דְחָרֶב:
@55 וְיָת כָּל עֲדָאַהּ תִּכְנוֹשׁ לְגוֹ פְתָיַהּ וְתוֹקֵד בְּנוּרָא יָת קַרְתָּא וְיָת כָּל עֲדָאַהּ גְמִיר קֳדָם יְיָ אֱלָהָךְ וּתְהֵי תֵּל חָרִיב לְעָלָם לָא תִתְבְּנֵי עוֹד:
@56 וְלָא יִדְבַּק בִּידָךְ מִדַעַם מִן חֶרְמָא בְּדִיל דִיתוּב יְיָ מִתְּקוֹף רוּגְזֵהּ וִיהַב לָךְ רַחֲמִין וִירַחַם עֲלָךְ וְיַסְגִנָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ:
@57 אֲרֵי תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבַּד דְכָשָׁר קֳדָם יְיָ אֱלָהָךְ:
@58 בְּנִין אַתּוּן קֳדָם יְיָ אֱלָהֲכוֹן לָא תִתְחַמְמוּן וְלָא תְשַׁווּן מְרָט בֵּין עֵינֵיכוֹן עַל מִית:
@59 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ וּבָךְ אִתִּרְעֵי יְיָ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכָּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@60 לָא תֵיכוּל כָּל דִמְרָחָק:
@61 דֵין בְּעִירָא דְתֵיכְלוּן תּוֹרִין אִמְרִין דִרְחֵלִין וְגָדְיָן דְעִזִין:
@62 אַיָלָא וְטַבְיָא וְיַחְמוּרָא וְיַעְלָא וְרֵימָא וְתוֹרְבָּלָא וְדִיצָא:
@63 וְכָל בְּעִירָא דִסְדִיקָא פַרְסָתָא וּמַטִלְפָא טִלְפִין תַּרְתֵּין פַּרְסָתָא מַסְקָא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:
@64 בְּרַם יָת דֵין לָא תֵיכְלוּן מִמַסְקֵי פִשְׁרָא וּמִמַסְדִיקֵי פַרְסָתָא מַטִלְפֵי טִלְפַיָא יָת גַמְלָא וְיָת אַרְנְבָא וְיָת טַּפְזָא אֲרֵי מַסְקֵי פִּשְׁרָא אִנוּן וּפַרְסָתְהוֹן לָא סְדִיקָא מְסָאֲבִין אִנוּן לְכוֹן:
@65 וְיָת חֲזִירָא אֲרֵי מַסְדִיק פַּרְסָתָא הוּא וְלָא פָשַׁר מְסָאָב הוּא לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבֵלְתְּהוֹן לָא תִקְרְבוּן:
@66 יָת דֵין תֵּיכְלוּן מִכֹּל דִי בְמַיָא כֹּל דִי לֵהּ צִיצִין וְקַלְפִין תֵּיכְלוּן:
@67 וְכֹל דִי לֵית לֵהּ צִיצִין וְקַלְפִין לָא תֵיכְלוּן מְסָאָב הוּא לְכוֹן:
@68 כָּל צִפַּר דַכְיָא תֵּיכְלוּן:
@69 וְדֵין דִי לָא תֵיכְלוּן מִנְהוֹן נִשְׁרָא וְעָר וְעַזְיָא:
@70 וּבַת כַּנְפָא וְטָרָפִיתָא וְדַיְתָא לִזְנַהּ:
@71 וְיָת כָּל עֹרְבָא לִזְנֵהּ:
@72 וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָּא וְנָצָא לִזְנוֹהִי:
@73 וְקַדְיָא וְקִפוֹפָא וּבַוְתָא:
@74 וְקָתָא וִירַקְרֵקָא וְשָׁלֵי נוּנָא:
@75 וְחַוָרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַר טוּרָא וַעֲטַּלֵפָא:
@76 וְכֹל רִחֲשָׁא דְעוֹפָא מְסָאָב הוּא לְכוֹן לָא יִתְאָכְלוּן:
@77 כָּל עוֹפָא דְכֵי תֵּיכְלוּן:
@78 לָא תֵיכְלוּן כָּל נְבִילָא לְתוֹתָב עָרֵל דִי בְקִרְוָיךְ תִּתְּנִנַהּ וְיֵיכְלִנַהּ אוֹ תְזַבְּנִנַהּ לְבַר עַמְמִין אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ לָא תֵיכוּל בְּשַׂר בַּחֲלָב:
@79 עַשְׂרָא תְעַשַׂר יָת כָּל עֲלָלַת זַרְעָךְ דְיִפּוֹק חַקְלָא שַׁתָּא בְשַׁתָּא:
@80 וְתֵיכוּל קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן מַעְשַׂר עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וּבְכוֹרֵי תוֹרָךְ וְעָנָךְ בְּדִיל דְתֵילַף לְמִדְחַל קֳדָם יְיָ אֱלָהָךְ כָּל יוֹמַיָא:
@81 וַאֲרֵי יִסְגֵי מִנָךְ אָרְחָא אֲרֵי לָא תִכּוּל לְמִטְלֵהּ אֲרֵי יִתְרָחַק מִנָךְ אַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן אֲרֵי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ:
@82 וְתִתֵּן בְּכַסְפָּא וּתְצוּר כַּסְפָּא בִּידָךְ וּתְהַךְ לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@83 וְתִתֵּן כַּסְפָּא בְּכֹל דִי יִתִּרְעֵי נַפְשָׁךְ בְּתוֹרֵי וּבְעָנָא וּבַחֲמַר חֲדַת וְעַתִּיק וּבְכֹל דִי תִשְׁאֲלִנָךְ נַפְשָׁךְ וְתֵיכוּל תַּמָן קֳדָם יְיָ אֱלָהָךְ וְתֶחֱדֵי אַתְּ וֶאֱנַשׁ בֵּיתָךְ:
@84 וְלֵוָאָה דִי בְקִרְוָיךְ לָא תִשְׁבְּקִנֵהּ אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמָךְ:
@85 מִסוֹף תְּלַת שְׁנִין תַּפֵק יָת כָּל מַעְשַׂר עֲלַלְתָּךְ בְּשַׁתָּא הַהִיא וְתַצְנַע בְּקִרְוָיךְ:
@86 וְיֵיתֵי לֵוָאָה אֲרֵי לֵית לֵהּ חֳלָק וְאַחֲסָנָא עִמָךְ וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בְקִרְוָיךְ וְיֵיכְלוּן וְיִשְׂבְּעוּן בְּדִיל דִי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עוֹבָדֵי יְדָךְ דִי תַעְבֵּד:
@87 מִסוֹף שְׁבַע שְׁנִין תַּעְבֵּד שְׁמִטְתָא:
@88 וְדֵין פִּתְגַם שְׁמִטְתָא דְתַשְׁמֵט כָּל גְבַר מַרֵי רְשׁוּ דִי יַרְשֵׁי בְּחַבְרֵהּ לָא יִתְבַּע מִן חַבְרֵהּ וּמִן אֲחוּהִי אֲרֵי קְרָא שְׁמִטְתָא קֳדָם יְיָ:
@89 מִן בַּר עַמְמִין תִּתְבַּע וְדִי יְהֵי לָךְ עִם אָחוּךְ תַּשְׁמֵט יְדָךְ:
@90 לְחוֹד אֲרֵי לָא יְהֵי בָךְ מִסְכֵּנָא אֲרֵי בָרָכָא יְבָרֵכִנָךְ יְיָ בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ:
@91 לְחוֹד אִם קַבָּלָא תְקַבֵּל לְמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@92 אֲרֵי יְיָ אֱלָהָךְ בָּרְכָךְ כְּמָא דִי מַלִיל לָךְ וְתוֹזֵף לְעַמְמִין סַגִיאִין וְאַתְּ לָא תְזוּף וְתִשְׁלוֹט בְּעַמְמִין סַגִיאִין וּבָךְ לָא יִשְׁלְטוּן:
@93 אֲרֵי יְהֵי בָךְ מִסְכֵּנָא מֵחַד מֵאַחָיךְ בַּחֲדָא מִקִרְוָיךְ בְּאַרְעָךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תַתְקֵף יָת לִבָּךְ וְלָא תִקְפֹּץ יָת יְדָךְ מֵאֲחוּךְ מִסְכֵּנָא:
@94 אֶלָא מִפְתַּח תִּפְתַּח יָת יְדָךְ לֵהּ וְאוֹזָפָא תּוֹזְפִנֵהּ כְּמִסַת חֶסְרוֹנֵהּ דְיַחֲסִיר לֵהּ:
@95 אִסְתַּמַר לָךְ דִילְמָא יְהֵי פִתְגָם עִם לִבָּךְ בִּרְשַׁע לְמֵימַר קְרִיבָא שַׁתָּא שְׁבִיעֲתָא שַׁתָּא דִשְׁמִטְתָא וְתַבְאֵשׁ עֵינָךְ בְּאָחוּךְ מִסְכֵּנָא וְלָא תִתֵּן לֵהּ וְיִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@96 מִתַּן תִתֵּן לֵהּ וְלָא יַבְאֵשׁ לִבָּךְ בְּמִתְּנָךְ לֵהּ אֲרֵי בְּדִיל פִּתְגָמָא הָדֵין יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עוֹבָדָךְ וּבְכֹל אוֹשָׁטוּת יְדָךְ:
@97 אֲרֵי לָא יִפְסוֹק מִסְכֵּנָא מִגוֹ אַרְעָא עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימַר מִפְתַּח תִּפְתַּח יָת יְדָךְ לַאֲחוּךְ לְעַנְיָךְ וּלְמִסְכֵּנָךְ בְּאַרְעָךְ:
@98 אֲרֵי יִזְדַבַּן לָךְ אֲחוּךְ בַּר יִשְׂרָאֵל אוֹ בַּת יִשְׂרָאֵל וְיִפְלְחִנָךְ שִׁית שְׁנִין וּבְשַׁתָּא שְׁבִיעֲתָא תִּפְטְרִנֵהּ בַּר חוֹרִין מֵעִמָךְ:
@99 וַאֲרֵי תִפְטְרִנֵה בַּר חוֹרִין מֵעִמָךְ לָא תִפְטְּרִנֵה רֵיקָן:
@100 אַפְרָשָׁא תַפְרֵשׁ לֵהּ מֵעָנָךְ וּמֵאִדְרָךְ וּמִמַעֲצַרְתָּךְ דִי בָרְכָךְ יְיָ אֱלָהָךְ תִּתֶּן לֵהּ:
@101 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ עַל כֵּן אֲנָא מְפַקְדָךְ יָת פִּתְגָמָא הָדֵין יוֹמָא דֵין:
@102 וִיהֵי אֲרֵי יֵימַר לָךְ לָא אֶפוֹק מֵעִמָךְ אֲרֵי רָחֲמָךְ וְיָת אֱנַשׁ בֵּיתָךְ אֲרֵי טַב לֵהּ עִמָךְ:
@103 וְתִסַב יָת מַרְצְעָא וְתִתֵּן בְּאֻדְנֵהּ וּבְדָשָׁא וִיהֵי לָךְ עִבֵד פָּלַח לְעָלָם וְאַף לְאַמְתָךְ תַּעְבֶּד כֵּן:
@104 לָא יִקְשֵׁי בְעֵינָךְ בְּמִפְטְרָךְ יָתֵהּ בַּר חוֹרִין מֵעִמָךְ אֲרֵי עַל חַד תְּרֵין כַּאֲגַר אֲגִירָא פָּלְחָךְ שִׁית שְׁנִין וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל דִי תַעְבֵּד:
@105 כָּל בּוּכְרָא דִי יִתְיְלִיד בְּתוֹרָךְ וּבְעָנָךְ דִכְרִין תַּקְדֵשׁ קָדָם יְיָ אֱלָהָךְ לָא תִפְלַח בְּבוּכְרָא דְתוֹרָךְ וְלָא תֵגוֹז בּוּכְרָא דְעָנָךְ:
@106 קֳדָם יְיָ אֱלָהָךְ תֵּיכְלִנֵהּ שַׁתָּא בְשַׁתָּא בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אַתְּ וֶאֱנַשׁ בֵּיתָךְ:
@107 וַאֲרֵי יְהֵי בֵהּ מוּמָא חֲגִיר אוֹ עֲוִיר כֹּל מוּם בִּישׁ לָא תִכְּסִנֵהּ קֳדָם יְיָ אֱלָהָךְ:
@108 בְּקִרְוָיךְ תֵּיכְלִנֵהּ מְסָאָבָא וְדַכְיָא כַּחֲדָא כִּבְסַר טַבְיָא וְאַיְלָא:
@109 לְחוֹד יָת דְמֵהּ לָא תֵיכוּל עַל אַרְעָא תִשְׁדִנֵהּ כְּמַיָא:
@110 טַר יָת יַרְחָא דַאֲבִיבָא וְתַעְבֵּד פִּסְחָא קֳדָם יְיָ אֱלָהָךְ אֲרֵי בְּיַרְחָא דַאֲבִיבָא אַפְּקָךְ יְיָ אֱלָהָךְ מִמִצְרַיִם וַעֲבַד לָךְ נִסִין בְּלֵילְיָא:
@111 וְתִכּוֹס פִּסְחָא קֳדָם יְיָ אֱלָהָךְ מִן בְּנֵי עָנָא וְנִכְסַת קוּדְשַׁיָא מִן תּוֹרֵי בְּאַתְרָא דִי יִתִּרְעֵי יְיָ לְאַשְׁרָאָה שְׁכִנְתֵּה תַּמָן:
@112 לָא תֵיכוּל עֲלוֹהִי חֲמִיעַ שִׁבְעָא יוֹמִין תֵּיכוּל עֲלוֹהִי פַטִיר לְחֵם עֹנִי אֲרֵי בִּבְהִילוּ נְפַקְתָּא מֵאַרְעָא דְמִצְרַיִם בְּדִיל דְתִדְכַּר יָת יוֹמָא מִפְּקָךְ מֵאַרְעָא דְמִצְרַיִם כָּל יוֹמֵי חַיָיךְ:
@113 וְלָא יִתְחֲזֵי לָךְ חֲמִר בְּכָל תְּחוּמָךְ שִׁבְעָא יוֹמִין וְלָא יְבִית מִן בִּסְרָא דִי תִכּוֹס בְּרַמְשָׁא בְּיוֹמָא קַדְמָאָה לְצַפְרָא:
@114 לֵית לָךְ רְשׁוּ לְמִכֹּס יָת פִּסְחָא בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@115 אֱלָהֵן לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן תִּכּוֹס יָת פִּסְחָא בְּרַמְשָׁא כְּמֵעַל שִׁמְשָׁא זְמַן מִפְקָךְ מִמִצְרָיִם:
@116 וּתְבַשֵׁל וְתֵיכוּל בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ וְתִתְפְּנֵי בְצַפְרָא וּתְהַךְ לְקִרְוָיךְ:
@117 שִׁתָּא יוֹמִין תֵּיכוּל פַּטִירָא וּבְיוֹמָא שְׁבִיעָאָה כְּנֵשׁ קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד עִבִידָא:
@118 שִׁבְעָא שָׁבוּעִין תִּמְנֵי לָךְ מִדְשַׁרְיוּת מַגְלָא בַּחֲצַד עוּמְרָא דַאֲרָמוּתָא תִּשְׁרֵי לְמִמְנֵּי שִׁבְעָא שָׁבוּעִין:
@119 וְתַעְבֵּד חַגָא דְשָׁבוּעַיָא קֳדָם יְיָ אֱלָהָךְ מִסַת נִדְבַת יְדָךְ דִי תִתֵּן כְּמָא דִי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ:
@120 וְתֶחֱדֵי קֳדָם יְיָ אֱלָהָךְ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה דִי בְקִרְוָיךְ וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בֵינָךְ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ לְאַשְׁרָאָה שְׁכִנְתֵּהּ תַּמָן:
@121 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרָיִם וְתִטַר וְתַעְבֵּד יָת קְיָמַיָא הָאִלֵין:
@122 חַגָא דִמְטָלַיָא תַּעְבֵּד לָךְ שִׁבְעָא יוֹמִין בְּמִכְנְשָׁךְ מֵאִדְרָךְ וּמִמַעְצַרְתָּךְ:
@123 וְתֶחֱדֵי בְּחַגָךְ אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְלֵוָאָה וְגִיוֹרָא וְיִתַּמָא וְאַרְמְלָא דִי בְקִרְוָיךְ:
@124 שִׁבְעָא יוֹמִין תֵּחוֹג קָדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי יְיָ אֲרֵי יְבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכָל עֲלַלְתָּךְ וּבְכָל עוֹבָדֵי יְדָיךְ וּתְהֵי בְּרַם חָדֵי:
@125 תְּלַת זִמְנִין בְּשַׁתָּא יִתְחֲזֵי כָל דְכוּרָךְ קֳדָם יְיָ אֱלָהָךְ בְּאַתְרָא דִי יִתִּרְעֵי בְּחַגָא דְפַטִירַיָא וּבְחַגָא דְשָׁבוּעַיָא וּבְחַגָא דִמְטָּלַיָא וְלָא יִתְחֲזֵי קֳדָם יְיָ רֵיקָנוּן:
@126 גְבַר כְּמַתְּנַת יְדֵהּ כְּבִרְכָּתָא דַיְיָ אֱלָהָךְ דִי יְהַב לָךְ: ססס:

@1 **ראה אנכי נתן לפניכם היום ברכה וקללה.** האמורות בהר גרזים ובהר עיבל:
@2 **את הברכה.** על מנת אשר תשמעו:
@3 **מן הדרך אשר אנכי מצוה אתכם היום ללכת** וגו' **.** הא למדת שכל העובד עבודה זרה הרי הוא סר מכל הדרך שנצטוו ישראל. מכאן אמרו כל המודה בעבודה זרה ככופר בכל התורה כלה:
@4 **ונתתה את הברכה.** כתרגומו ית מברכיא, את המברכים: **על הר גרזים.** כלפי הר גרזים, הופכין פניהם ופתחו בברכה, ברוך האיש אשר לא יעשה פסל ומסכה וגו' . כל הארורים שבפרשה אמרו תחלה בלשון ברוך, ואחר כך הפכו פניהם כלפי הר עיבל ופתחו בקללה:
@5 **הלא המה.** נתן בהם סימן: **אחרי.** אחרי העברת הירדן הרבה והלאה למרחוק. וזהו לשון אחרי. כל מקום שנאמר אחרי, מפלג הוא: **דרך מבוא השמש.** להלן מן הירדן לצד מערב. וטעם המקרא מוכיח שהם שני דברים, שננקדו בשני טעמים, אחרי, נקוד בפשטא, ודרך, נקוד במשפל והוא דגש, ואם היה אחרי דרך, דבור אחד, היה נקוד אחרי, במשרת, בשופר הפוך, ודרך, בפשטא ורפה: **מול הגלגל.** רחוק מן הגלגל: **אלוני מרה.** שכם הוא, שנאמר (בראשית יב, ו) עד מקום שכם עד אלון מרה:
@6 **כי אתם עברים את הירדן** וגו' **.** נסים של ירדן יהיו סימן בידכם שתבואו ותירשו את הארץ:
@9 **אבד תאבדון.** אבד ואחר כך תאבדון מכאן לעוקר עבודה זרה שצריך לשרש אחריה: **את כל המקומות אשר עבדו שם** וגו' **.** ומה תאבדון מהם, את אלהיהם אשר על ההרים:
@10 **מזבח.** של אבנים הרבה: **מצבה.** של אבן אחת, והוא בימוס ששנויה במשנה (ע''ז מז, ב) אבן שחצבה מתחלתה לבימוס: **אשרה.** אילן הנעבד: **ואבדתם את שמם.** לכנות להם שם לגנאי, בית גליא קורין לה בית כריא, עין כל עין קוץ:
@11 **לא תעשון כן.** להקטיר לשמים בכל מקום (פסוק ה) , כי אם במקום אשר יבחר. דבר אחר ונתצתם את מזבחתם ואבדתם את שמם לא תעשון כן, אזהרה למוחק את השם ולנותץ אבן מן המזבח או מן העזרה. אמר רבי ישמעאל וכי תעלה על דעתך שישראל נותצין את המזבחות, אלא שלא תעשו כמעשיהם, ויגרמו עונותיכם למקדש אבותיכם שיחרב:
@12 **לשכנו תדרשו.** זה משכן שילה:
@13 **וזבחיכם.** שלמים של חובה: **מעשרתיכם.** מעשר בהמה ומעשר שני לאכול לפנים מן החומה: **תרומת ידכם.** אלו הבכורים, שנאמר בהם (דברים כו, ד) ולקח הכהן הטנא מידך: **ובכורות בקרכם.** לתתם לכהן ויקריבם שם:
@14 **אשר ברכך ה'.** לפי הברכה הבא:
@15 **לא תעשון ככל אשר אנחנו עשים** וגו' **.** מוסב למעלה (דברים יא, לא) על כי אתם עברים את הירדן וגו' כשתעברו את הירדן, מיד מתרים אתם להקריב בבמה, כל ארבע עשרה שנה של כבוש וחלוק, ובבמה לא תקריבו כל מה שאתם מקריבים פה היום במשכן, שהוא עמכם ונמשח והוא כשר להקריב בו חטאות ואשמות נדרים ונדבות, אבל בבמה אין קרב אלא הנדר והנדב. וזהו איש כל הישר בעיניו, נדרים ונדבות שאתם מתנדבים על ידי שיישר בעיניכם להביאם ולא על ידי חובה, אותם תקריבו בבמה:
@16 **כי לא באתם.** כל אותן ארבע עשרה שנה: **אל המנוחה.** זו שילה: **הנחלה.** זו ירושלים: **עד עתה.** כמו עדין:
@17 **ועברתם את הירדן וישבתם בארץ.** משתחלקוה ויהא כל אחד מכיר את חלקו ואת שבטו: **והניח לכם.** לאחר כבוש וחלוק ומנוחה (שופטים ג, א) מן הגוים אשר הניח ה' לנסות בם את ישראל. ואין זאת אלא בימי דוד, אז:
@18 **והיה המקום** וגו' **.** בנו לכם בית הבחירה בירושלים. וכן הוא אומר בדוד (שמואל ב' ז, א. ב) ויהי כי ישב המלך בביתו, וה' הניח לו מסביב מכל אויביו. ויאמר המלך אל נתן הנביא ראה נא אנכי יושב בבית ארזים, וארון האלהים ישב בתוך היריעה: **שמה תביאו** וגו' **.** למעלה אמרו (פסוק ו) לענין שילה וכאן אמור לענין ירושלים, ולכך חלקם הכתוב, לתן התר בין זו לזו, משחרבה שילה ובאו לנוב, וחרבה נוב ובאו לגבעון, היו הבמות מתרות עד שבאו לירושלים: **מבחר נדריכם.** מלמד שיביאו מן המבחר:
@20 **השמר לך.** לתן לא תעשה על הדבר. **בכל מקום אשר תראה.** אשר יעלה בלבך, אבל אתה מקריב על פי נביא, כגון אליהו בהר הכרמל:
@21 **באחד שבטיך.** בחלקו של בנימין. ולמעלה הוא אומר (פסוק ה) מכל שבטיכם. הא כיצד, כשקנה דוד את הגרן מארונה היבוסי גבה הזהב מכל השבטים, ומכל מקום הגרן בחלקו של בנימין היה:
@22 **רק בכל אות נפשך.** במה הכתוב מדבר, אם בבשר תאוה להתירה להם בלא הקרבת אמורים, הרי הוא אומר במקום אחר (פסוק כ) כי ירחיב ה' אלהיך את גבולך וגו' ואמרת אכלה בשר וגו', במה זה מדבר, בקדשים שנפל בהם מום, שיפדו ויאכלו בכל מקום. יכול יפדו על מום עובר, תלמוד לומר רק: **תזבח ואכלת.** אין לך בהם התר גזה וחלב, אלא אכילה על ידי זביחה: **הטמא והטהור.** לפי שבאו מכח קדשים, שנאמר בהם (ויקרא ז, יט) והבשר אשר יגע בכל טמא לא יאכל, הצרך להתיר בו, שטמא וטהור אוכלין בקערה אחת: **כצבי וכאיל.** שאין קרבן בא מהם: **כצבי וכאיל.** לפטרן מן הזרוע והלחיים והקבה:
@23 **רק הדם לא תאכלו.** אף על פי שאמרתי שאין לך בו זריקת דם במזבח, לא תאכלנו: **תשפכנו כמים.** לומר לך שאין צריך כסוי. דבר אחר הרי הוא כמים להכשיר את הזרעים:
@24 **לא תוכל.** בא הכתוב לתן לא תעשה על הדבר. רבי יהושע בן קרחה אומר יכול אתה, אבל אינך רשאי, כיוצא בו (יהושע טו, סג) ואת היבוסי יושבי ירושלים לא יכלו בני יהודה להורישם, יכולים היו, אלא שאינן רשאין, לפי שכרת להם אברהם ברית כשלקח מהם מערת המכפלה. ולא יבוסים היו אלא חתיים היו, אלא על שם העיר ששמה יבוס [נקראים יבוסים] . כך מפורש בפרקי דרבי אליעזר. והוא שנאמר (שמואל ב' ה, ו) כי אם הסירך העורים והפסחים, צלמים שכתבו עליהם את השבועה: **ובכרת בקרך.** אזהרה לכהנים: **ותרומת ידך.** אלו הבכורים:
@25 **לפני ה'.** לפנים מן החומה: **והלוי אשר בשעריך.** אם אין לך לתת לו מחלקו, כגון מעשר ראשון, תן לו מעשר עני. אין לך מעשר עני, הזמינהו על שלמיך:
@26 **השמר לך.** לתן לא תעשה על הדבר: **על אדמתך.** אבל בגולה אינך מזהר עליו יותר מעניי ישראל:
@27 **כי ירחיב** וגו' **.** למדה תורה דרך ארץ, שלא יתאוה אדם לאכול בשר, אלא מתוך רחבת ידים ועושר: **בכל אות נפשך** וגו' **.** אבל במדבר נאסר להם בשר חלין, אלא אם כן מקדישה ומקריבה שלמים:
@28 **כי ירחק ממך המקום.** ולא תוכל לבוא ולעשות שלמים בכל יום כמו עכשיו שהמשכן הולך עמכם: **וזבחת** וגו' **כאשר צויתך.** למדנו שיש צווי בזביחה היאך ישחוט, והן הלכות שחיטה שנאמרו למשה בסיני:
@29 **אך כאשר יאכל את הצבי** וגו' **.** אינך מזהר לאכלן בטהרה. אי מה צבי ואיל חלבן מתר, אף חלין חלבן מתר, תלמוד לומר אך:
@30 **רק חזק לבלתי אכל הדם.** ממה שנאמר חזק אתה למד שהיו שטופים בדם לאכלו, לפיכך הצרך לומר חזק, דברי רבי יהודה. רבי שמעון בן עזאי אומר, לא בא הכתוב אלא להזהירך וללמדך עד כמה אתה צריך להתחזק במצות, אם הדם, שהוא קל להשמר ממנו, שאין אדם מתאוה לו, הצרך לחזקך באזהרתו, קל וחמר לשאר מצות: **ולא תאכל הנפש עם הבשר.** אזהרה לאבר מן החי:
@31 **לא תאכלנו.** אזהרה לדם התמצית:
@32 **לא תאכלנו.** אזהרה לדם האיברים: **למען ייטב לך** וגו' **.** צא ולמד מתן שכרן של מצות, אם הדם שנפשו של אדם קצה ממנו, הפורש ממנו זוכה לו ולבניו אחריו, קל וחמר לגזל ועריות שנפשו של אדם מתאוה להם:
@33 **רק קדשיך.** אף על פי שאתה מתר לשחוט חלין, לא התרתי לך לשחוט את הקדשים ולאכלן בשעריך בלא הקרבה, אלא הביאם לבית הבחירה:
@34 **ועשית עלתיך.** אם עולות הם תן הבשר והדם על גבי המזבח, ואם זבחי שלמים הם, דם זבחיך ישפך על המזבח תחלה ואחר כך והבשר תאכל. ועוד דרשו רבותינו (פסוק כו) , רק קדשיך בא ללמד על הקדשים שבחוצה לארץ וללמד על התמורות ועל ולדות קדשים שיקריבו:
@35 **שמר.** זו משנה שאתה צריך לשמרה בבטנך שלא תשכח. כענין שנאמר (משלי כב) כי נעים כי תשמרם בבטנך, ואם שנית אפשר שתשמע ותקיים, הא כל שאינו בכלל משנה אינו בכלל מעשה: **את כל הדברים.** שתהא חביבה עליך מצוה קלה כמצוה חמורה: **הטוב.** בעיני השמים: **והישר.** בעיני אדם:
@37 **פן תנקש.** אנקלוס תרגם לשון מוקש. ואני אומר שלא חש לדקדק בלשון, שלא מצינו נו''ן בלשון יוקש ואפלו ליסוד הנופל ממנו, אבל בלשון טרוף וקשקוש מצינו נו''ן (דניאל ה, ו) וארכבתה דא לדא נקשן. ואף זה אני אומר, פן תנקש אחריהם פן תטרף אחריהם להיות כרוך אחר מעשיהם, וכן (תהלים קט, יא) ינקש נושה לכל אשר לו, מקלל את הרשע להיות עליו נושים רבים והיו מחזירין ומנקשין אחר ממונו: **אחרי השמדם מפניך.** אחר שתראה שאשמידם מפניך, יש לך לתת לב מפני מה נשמדו אלו, מפני מעשים מקלקלים שבידיהם, אף אתה לא תעשה כן שלא יבואו אחרים וישמידוך: **איכה יעבדו.** לפי שלא ענש על עבודת אלילים אלא על זבוח וקטור ונסוך והשתחואה, כמו שכתוב (שמות כב, יט) בלתי לה' לבדו, דברים הנעשים לגבוה, בא ולמדך כאן, שאם דרכה של עבודה זרה לעבדה בדבר אחר, כגון פוער לפעור, וזורק אבן למרקוליס, זו היא עבודתה וחיב. אבל זבוח וקטור ונסוך והשתחואה, אפלו שלא כדרכה חיב:
@38 **כי גם את בניהם.** גם, לרבות את אבותיהם ואמותיהם. אמר ר' עקיבא אני ראיתי נכרי שכפתו לאביו לפני כלבו ואכלו:
@39 **את כל הדבר.** קלה כחמורה: **תשמרו לעשות.** לתן לא תעשה על עשה האמורים בפרשה. שכל השמר לשון לא תעשה הוא, אלא שאין לוקין על השמר של עשה: **לא תסף עליו.** חמשה טוטפות בתפלין, חמשה מינין בלולב, ארבע ברכות בברכת כהנים:
@40 **ונתן אליך אות.** בשמים, כענין שנאמר בגדעון (שופטים ו, יז) ועשית לי אות, ואומר (שם ו, לט) יהי נא חרב אל הגזה וגו' : **או מופת.** בארץ. [ ס''א אות . בשמים , דכתיב (בראשית א, יד) והיו לאתת ולמועדים או מופת . בארץ . דכתיב (שופטים שם) אם טל יהיה על הגזה לבדה ועל כל הארץ חרב ] אף על פי כן לא תשמע לו. ואם תאמר מפני מה נותן לו הקדוש ברוך הוא ממשלה לעשות אות, כי מנסה ה' אלהיכם אתכם:
@43 **ואת מצותיו תשמרו.** תורת משה: **ובקולו תשמעו.** בקול הנביאים: **ואתו תעבדו.** במקדשו: **ובו תדבקון.** הדבק בדרכיו. גמול חסדים, קבור מתים, בקר חולים, כמו שעשה הקדוש ברוך הוא:
@44 **סרה.** דבר המוסר מן העולם שלא היה ולא נברא ולא צויתיו לדבר כן, דישטולוד''א בלע''ז : **והפדך מבית עבדים.** אפלו אין לו עליך אלא שפדאך, דיו:
@45 **כי יסיתך.** אין הסתה אלא גרוי, שנאמר (שמואל א' כו, יט) אם ה' הסיתך בי, אמיטר''א בלע''ז , שמשיאו לעשות כן: **אחיך.** מאב: **בן אמך.** מאם: **חיקך.** השוכבת בחיקך ומחקה בך אפיקייד''א בלע''ז , וכן (יחזקאל מג, יד) ומחיק הארץ, מיסוד התקוע בארץ: **אשר כנפשך.** זה אביך. פרש לך הכתוב את החביבין לך, קל וחמר לאחרים: **בסתר.** דבר הכתוב בהוה, שאין דברי מסית אלא בסתר. וכן שלמה הוא אומר (משלי ז, ט) בנשף בערב יום באישון לילה ואפלה: **אשר לא ידעת אתה ואבתיך.** דבר זה גנאי גדול הוא לך שאף האמות אין מניחין מה שמסרו להם אבותיהם, וזה אומר לך עזוב מה שמסרו לך אבתיך:
@46 **הקרבים אליך או הרחקים.** למה פרט קרובים ורחוקים, אלא כך אמר הכתוב, מטיבן של קרובים אתה למד טיבן של רחוקים, כשם שאין ממש בקרובים כך אין ממש ברחוקים: **מקצה הארץ.** זו חמה ולבנה וצבא השמים שהן מהלכין מסוף העולם ועד סופו:
@47 **לא תאבה לו.** לא תהא תאב לו. לא תאהבנו. לפי שנאמר (ויקרא יט, יח) ואהבת לרעך כמוך, את זה לא תאהב: **ולא תשמע אליו.** בהתחננו על נפשו למחול לו, לפי שנאמר (שמות כג, ה) עזב תעזב עמו, לזה לא תעזוב: **ולא תחוס עינך עליו.** לפי שנאמר (ויקרא יט, טז) לא תעמד על דם רעך, על זה לא תחוס: **ולא תחמול.** לא תהפך בזכותו: **ולא תכסה עליו.** אם אתה יודע לו חובה אינך רשאי לשתוק:
@48 **כי הרג תהרגנו.** אם יצא מבית דין זכאי, החזירהו לחובה. יצא מבית דין חיב, אל תחזירהו לזכות: **ידך תהיה בו בראשונה.** מצוה ביד הנסת להמיתו. לא מת בידו, ימות ביד אחרים, שנאמר ויד כל העם וגו' :
@51 **לשבת שם.** פרט לירושלים שלא נתנה לדירה: **כי תשמע** וגו' **לאמר.** אומרים כן, יצאו וגו' :
@52 **בני בליעל.** בלי עול. שפרקו עלו של מקום: **אנשים.** ולא נשים: **ישבי עירם.** ולא יושבי עיר אחרת. מכאן אמרו אין נעשית עיר הנדחת עד שידיחוה אנשים, ועד שיהיו מדיחיה מתוכה:
@53 **ודרשת וחקרת ושאלת היטב.** מכאן למדו שבע חקירות מרבוי המקרא. כאן יש שלש דרישה וחקירה והיטב. ושאלת, אינו מן המנין, וממנו למדו בדיקות. ובמקום אחר הוא אומר (דברים יט, יח) ודרשו השופטים היטב. ועוד במקום אחר הוא אומר (שם יז, ד) ודרשת היטב. ולמדו היטב היטב לגזרה שוה, לתן האמור של זה בזה:
@54 **הכה תכה.** אם אינך יכול להמיתם במיתה הכתובה בהם, המיתם באחרת:
@55 **לה' אלהיך.** לשמו ובשבילו:
@56 **למען ישוב ה' מחרון אפו.** שכל זמן שעבודה זרה בעולם, חרון אף בעולם:
@58 **לא תתגדדו.** לא תתנו גדידה ושרט בבשרכם על מת כדרך שהאמוריים עושין, לפי שאתם בניו של מקום ואתם ראויין להיות נאים ולא גדודים ומקורחים: **בין עיניכם.** אצל הפדחת. ובמקום אחר הוא אומר (ויקרא כא, ה) לא יקרחו קרחה בראשם, לעשות כל הראש כבין העינים:
@59 **כי עם קדוש אתה.** קדשת עצמך מאבותיך. ועוד, ובך בחר ה':
@60 **כל תועבה.** כל שתעבתי לך, שאם צרם אזן בכור כדי לשחטו במדינה, הרי דבר שתעבתי לך כל מום לא יהיה בו, ובא ולמד כאן שלא ישחט ויאכל על אותו המום. בשל בשר בחלב הרי דבר שתעבתי לך, והזהיר כאן על אכילתו:
@62 **זאת הבהמה** וגו'' **איל וצבי ויחמור.** למדנו שהחיה בכלל בהמה, ולמדנו שבהמה וחיה טמאה מרבה מן הטהורה, שבכל מקום פורט את המועט: **ואקו.** מתרגם יעלא (איוב לט, א) יעלי סלע הוא אשטנבו''ק : **ותאו.** תורבלא, שור היער. באלא יער, בלשון ארמי:
@63 **מפרסת.** סדוקה כתרגומו: **פרסה.** פלנט''א [כף רגל] : **ושסעת.** חלוקה בשתי צפרנים. שיש סדוקה ואינה חלוקה בצפרנים והיא טמאה: **בבהמה.** משמע מה שנמצא בבהמה אכל, מכאן אמרו שהשליל נתר בשחיטת אמו:
@64 **השסועה.** בריה היא שיש לה שני גבין ושתי שדראות. אמרו רבותינו למה נשנו, בבהמות מפני השסועה, ובעופות מפני הראה, שלא נאמרו בתורת כהנים:
@65 **ובנבלתם לא תגעו.** רבותינו פרשו, ברגל. שאדם חיב לטהר את עצמו ברגל. יכול יהיו מזהרים בכל השנה, תלמוד לומר (ויקרא כא, א) אמור אל הכהנים וגו' ומה טמאת המת חמורה, כהנים מזהרים ואין ישראל מזהרים, טמאת נבלה קלה לא כל שכן:
@68 **כל צפור טהורה תאכלו.** להתיר משלחת שבמצורע:
@69 **וזה אשר לא תאכלו מהם.** לאסר את השחוטה:
@70 **והראה ואת האיה** וגו' **.** היא ראה היא איה היא דיה. ולמה נקרא שמה ראה, שרואה ביותר. ולמה הזהיר בכל שמותיה, שלא לתן פתחון פה לבעל דין לחלוק, שלא יהא האוסרה קורא אותה ראה והבא להתיר אומר, זו דיה שמה או איה שמה, וזו לא אסר הכתוב. ובעופות פרט לך הטמאים, ללמד שהעופות הטהורים מרבים על הטמאים, לפיכך פרט את המועט:
@73 **והתנשמת.** קלב''א שורי''ץ :
@74 **שלך.** השולה דגים מן הים:
@75 **דוכיפת.** הוא תרנגול הבר ובלע''ז הרופ''א וכרבלתו כפולה:
@76 **שרץ העוף.** הם הנמוכים הרוחשים על הארץ, כגון זבובין וצרעים וחגבים טמאים, הם קרויים שרץ:
@77 **כל עוף טהור תאכלו.** ולא את הטמא. בא לתן עשה על לא תעשה. וכן בבהמה, אותה תאכלו ולא בהמה טמאה, לאו הבא מכלל עשה, עשה, לעבור עליהם בעשה ולא תעשה:
@78 **לגר אשר בשעריך.** גר תושב שקבל עליו שלא לעבוד עבודה זרה ואוכל נבלות: **כי עם קדוש אתה לה'.** קדש את עצמך במתר לך. דברים המתרים ואחרים נוהגים בהם אסור, אל תתירם בפניהם: **לא תבשל גדי.** שלש פעמים. פרט לחיה ולעופות ולבהמה טמאה: **לא תבשל גדי** וגו':
@79 **עשר תעשר.** מה ענין זה אצל זה, אמר להם הקדוש ברוך הוא לישראל, לא תגרמו לי לבשל גדיים של תבואה עד שהן במעי אמותיהן, שאם אין אתם מעשרים מעשרות כראוי, כשהוא סמוך להתבשל אני מוציא רוח קדים והיא משדפתן. שנאמר (מלכים ב' יט, כא) ושדפה לפני קמה, וכן לענין בכורים: **שנה שנה.** מכאן שאין מעשרין מן החדש על הישן:
@80 **ואכלת** וגו' **.** זה מעשר שני. שכבר למדנו לתן מעשר ראשון ללוים, שנאמר (במדבר יח, כו) כי תקחו מאת בני ישראל וגו' , ונתן להם רשות לאכלו בכל מקום, שנאמר (שם יח, לא) ואכלתם אתו בכל מקום, על כרחך זה מעשר אחר הוא:
@81 **כי יברכך.** שתהא התבואה מרבה לשאת:
@83 **בכל אשר תאוה נפשך.** כלל: **בבקר ובצאן וביין ובשכר.** פרט: **ובכל אשר תשאלך נפשך.** חזר וכלל. מה הפרט מפורש ולד ולדות הארץ וראוי למאכל אדם וכו' :
@84 **והלוי** וגו' **לא תעזבנו.** מלתן לו מעשר ראשון: **כי אין לו חלק ונחלה עמך.** יצאו לקט שכחה ופאה והפקר, שאף הוא יש לו חלק עמך בהן כמוך, ואינן חיבין במעשר:
@85 **מקצה שלש שנים.** בא ולמד שאם השהה מעשרותיו של שנה ראשונה ושניה לשמטה, שיבערם מן הבית בשלישית:
@86 **ובא הלוי.** ויטול מעשר ראשון: **והגר והיתום.** ויטלו מעשר שני, שהוא של עני של שנה זו, ולא תאכלנו אתה בירושלים כדרך שנזקקת לאכול מעשר שני של שתי שנים: **ואכלו ושבעו.** תן להם כדי שביעה. מכאן אמרו אין פוחתין לעני בגורן וכו' . ואתה הולך לירושלים למעשר של שנה ראשונה ושניה שהשהית ומתודה בערתי הקדש מן הבית (דברים כו, יג) , כמו שמפורש ב''כי תכלה לעשר'' (שם כו, יב) :
@87 **מקץ שבע שנים.** יכול שבע שנים לכל מלוה ומלוה, תלמוד לומר (פסוק ט) קרבה שנת השבע. ואם אתה אומר שבע שנים לכל מלוה ומלוה להלואת כל אחד ואחד, היאך היא קרבה, הא למדת שבע שנים למנין השמטות:
@88 **שמוט כל בעל משה ידו.** שמוט את ידו של כל בעל משה:
@89 **את הנכרי תגש.** זו מצות עשה:
@90 **אפס כי לא יהיה בך אביון.** ולהלן הוא אומר (פסוק יא) כי לא יחדל אביון, אלא בזמן שאתם עושים רצונו של מקום, אביונים באחרים ולא בכם, וכשאין אתם עושים רצונו של מקום אביונים בכם: **אביון.** דל מעני, ולשון אביון שהוא תאב לכל דבר:
@91 **רק אם שמוע תשמע.** אז לא יהיה בך אביון: **שמוע תשמע.** שמע קמעא משמיעין אותו הרבה:
@92 **כאשר דבר לך.** והיכן דבר, ברוך אתה בעיר: (דברים כח, ג) **והעבטת.** כל לשון הלואה כשנופל על המלוה, נופל בלשון מפעיל. כגון והלוית, והעבטת. ואם היה אומר ועבטת היה נופל על הלוה, כמו ולוית: **והעבטת גוים.** יכול שתהא לוה מזה ומלוה לזה, תלמוד לומר ואתה לא תעבט: **ומשלת בגוים רבים.** יכול גוים אחרים מושלים עליך, תלמוד לומר ובך לא ימשלו:
@93 **כי יהיה בך אביון.** התאב תאב קודם: **מאחד אחיך.** אחיך מאביך, קודם לאחיך מאמך: **שעריך.** עניי עירך קודמים לעניי עיר אחרת: **לא תאמץ.** יש לך אדם שמצטער אם יתן אם לא יתן, לכך נאמר לא תאמץ. יש לך אדם שפושט את ידו וקופצה, לכך נאמר ולא תקפץ: **מאחיך האביון.** אם לא תתן לו, סופך להיות אחיו בעניות [של אביון] :
@94 **פתח תפתח.** אפלו כמה פעמים: **כי פתח תפתח.** הרי כי משמש בלשון אלא: **והעבט תעביטנו.** אם לא רצה במתנה, תן לו בהלואה: **די מחסרו.** ואי אתה מצוה להעשירו: **אשר יחסר לו.** אפלו סוס לרכוב עליו ועבד לרוץ לפניו: **לו.** זו אשה. וכן הוא אומר (בראשית ב, יח) אעשה לו עזר כנגדו:
@95 **וקרא עליך.** יכול מצוה, תלמוד לומר (דברים כד, טו) ולא יקרא: **והיה בך חטא.** מכל מקום, אפלו לא יקרא. אם כן למה נאמר וקרא עליך, ממהר אני לפרע על ידי הקורא יותר ממי שאינו קורא:
@96 **נתון תתן לו.** אפלו מאה פעמים: **לו.** בינו ובינך: **כי בגלל הדבר.** אפלו אמרת לתן, אתה נוטל שכר האמירה עם שכר המעשה:
@97 **על כן.** מפני כן: **לאמר.** עצה לטובתך אני משיאך: **לאחיך לעניך.** לאיזה אח, לעני: **לעניך.** ביו''ד אחד, לשון עני אחד הוא. אבל ענייך בשני יודי''ן, שני עניים:
@98 **כי ימכר לך.** על ידי אחרים, שמכרוהו בית דין בגנבתו הכתוב מדבר. והרי כבר נאמר (שמות כא, ב) כי תקנה עבד עברי, ובמכרוהו בית דין הכתוב מדבר. אלא מפני שני דברים שנתחדשו כאן. אחד שכתוב או העבריה, אף היא תצא בשש. ולא שמכרוה בית דין, שאין האשה נמכרת בגנבתה, שנאמר בגנבתו ולא בגנבתה, אלא בקטנה שמכרה אביה, ולמד כאן שאם יצאו שש שנים קודם שתביא סימנין תצא. ועוד חדש כאן (פסוק יד) העניק תעניק:
@100 **העניק תעניק.** לשון עדי בגובה ובמראית העין, שיהא נכר שהטיבות לו. ויש מפרשים לשון הטענה על צוארו: **מצאנך ומגרנך ומיקבך.** יכול אין לי אלא אלו בלבד, תלמוד לומר אשר ברכך, מכל מה שברכך בוראך. ולמה נאמרו אלו, מה אלו מיוחדים שהם בכלל ברכה אף כל שהוא בכלל ברכה, יצאו פרדות. ולמדו רבותינו במסכת קדושין (יז, א) בגזרה שוה כמה נותן לו מכל מין ומין:
@101 **וזכרת כי עבד היית.** והענקתי ושניתי לך מבזת מצרים ובזת הים, אף אתה הענק ושנה לו:
@103 **עבד עולם.** יכול כמשמעו, תלמוד לומר (ויקרא כה, י) ושבתם איש אל אחזתו ואיש אל משפחתו תשובו, הא למדת שאין זה, אלא עולמו של יובל: **ואף לאמתך תעשה כן.** הענק לה. יכול אף לרציעה השוה הכתוב אותה, תלמוד לומר (שמות כא, ה) ואם אמר יאמר העבד, עבד נרצע, ואין אמה נרצעת:
@104 **כי משנה שכר שכיר.** מכאן אמרו עבד עברי עובד בין ביום ובין בלילה. וזהו כפלים שבעבודת שכירי יום. ומהו עבודתו בלילה, רבו מוסר לו שפחה כנענית והולדות לאדון:
@105 **כל הבכור** וגו' **תקדיש.** ובמקום אחר הוא אומר לא יקדיש, שנאמר (ויקרא כז, כו) אך בכור אשר יבכר לה' וגו' , הא כיצד, אינו מקדישו לקרבן אחר, וכאן למד שמצוה לומר הרי אתה קדוש לבכורה. דבר אחר אי אפשר לומר תקדיש שכבר נאמר לא יקדיש, ואי אפשר לומר לא יקדיש שהרי כבר נאמר תקדיש, הא כיצד, מקדישו אתה הקדש עלוי, ונותן להקדש כפי טובת הנאה שבו: **לא תעבד בבכור שורך ולא תגז** וגו' **.** אף החלוף למדו רבותינו שאסור, אלא שדבר הכתוב בהוה:
@106 **לפני ה' אלהיך תאכלנו.** לכהן הוא אומר, שכבר מצינו שהוא ממתנות כהנה אחד תם ואחד בעל מום, שנאמר (במדבר יח, יח) ובשרם יהיה לך וגו' : **שנה בשנה.** מכאן שאין משהין אותו יותר על שנתו. יכול יהא פסול משעברה שנתו, כבר הקש למעשר, שנאמר (לעיל יד, כג) ואכלת לפני ה' אלהיך מעשר דגנך תירשך ויצהרך ובכרת בקרך וצאנך, מה מעשר שני אינו נפסל משנה לחברתה, אף בכור אינו נפסל, אלא שמצוה תוך שנתו: **שנה בשנה.** אם שחטו בסוף שנתו, אוכלו אותו היום ויום אחד משנה אחרת. למד שנאכל לשני ימים ולילה אחד:
@107 **מום.** כלל: **פסח או עור.** פרט: **כל מום רע.** חזר וכלל. מה הפרט מפורש מום הגלוי ואינו חוזר, אף כל מום שבגלוי ואינו חוזר:
@109 **רק את דמו לא תאכל.** שלא תאמר הואיל וכלו התר הבא מכלל אסור הוא, שהרי קדוש ונשחט בחוץ בלא פדיון ונאכל, יכול יהא אף הדם מתר, תלמוד לומר רק את דמו לא תאכל:
@110 **שמור את חדש האביב.** מקודם בואו שמור, שיהא ראוי לאביב להקריב בו את מנחת העמר, ואם לאו, עבר את השנה: **ממצרים לילה.** והלא ביום יצאו, שנאמר (במדבר לג, ג) ממחרת הפסח יצאו בני ישראל וגו' , אלא לפי שבלילה נתן להם פרעה רשות לצאת, שנאמר (שמות יב, לא) ויקרא למשה ולאהרן לילה וגו' :
@111 **וזבחת פסח לה' אלהיך צאן.** שנאמר (שמות יב, ה) מן הכבשים ומן העזים תקחו: **ובקר.** תזבח לחגיגה. שאם נמנו על הפסח חבורה מרבה, מביאים עמו חגיגה כדי שיהא נאכל על השובע, ועוד למדו רבותינו דברים הרבה מפסוק זה:
@112 **לחם עני.** לחם שמזכיר את העוני שנתענו במצרים: **כי בחפזון יצאת.** ולא הספיק בצק להחמיץ וזה יהיה לך לזכרון. וחפזון לא שלך היה אלא של מצרים, שכן הוא אומר (שמות יב, לג) ותחזק מצרים על העם וגו' : **למען תזכר.** על ידי אכילת הפסח והמצה, את יום צאתך:
@113 **ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר.** אזהרה למותיר בפסח דורות, לפי שלא נאמר אלא בפסח מצרים, ויום ראשון האמור כאן הוא ארבעה עשר בניסן, כמה דאתאמר (שמות יב, טו) אך ביום הראשון תשביתו שאר מבתיכם. ולפי שנסתלק הכתוב מענינו של פסח והתחיל לדבר בחקות שבעת ימים, כגון שבעת ימים תאכל עליו מצות ולא יראה לך שאור בכל גבולך, הצרך לפרש באיזו זביחה הוא מזהיר, שאם כתב ולא ילין מן הבשר אשר תזבח בערב לבקר הייתי אומר שלמים הנשחטים כל שבעה כלן בבל תותירו ואינן נאכלין אלא ליום ולילה, לכך כתב בערב ביום הראשון. דבר אחר בחגיגת ארבעה עשר הכתוב מדבר, ולמד עליה שנאכלת לשני ימים. והראשון האמור כאן, ביום טוב הראשון הכתוב מדבר. וכן משמעות המקרא, בשר חגיגה אשר תזבח בערב, לא ילין ביום טוב הראשון עד בקרו של שני, אבל נאכלת היא בארבעה עשר ובחמשה עשר, כך היא שנויה במסכת פסחים (עא ב) :
@115 **בערב כבוא השמש מועד צאתך ממצרים.** הרי שלשה זמנים חלוקים, בערב, משש שעות ולמעלה זבחהו. וכבוא השמש, תאכלהו. ומועד צאתך, אתה שורפהו. כלומר, נעשה נותר ויצא לבית השרפה:
@116 **ובשלת.** זהו צלי אש, שאף הוא קרוי בשול: **ופנית בבקר.** לבקרו של שני, מלמד שטעון לינה ליל של מוצאי יום טוב:
@117 **ששת ימים תאכל מצות.** ובמקום אחר הוא אומר (שמות יב, טו) שבעת ימים, שבעה מן הישן וששה מן החדש. דבר אחר למד על אכילת מצה בשביעי, שאינה חובה, ומכאן אתה למד לששת ימים. שהרי שביעי בכלל היה ויצא מן הכלל ללמד, שאין אכילת מצה בו חובה אלא רשות, ולא ללמד על עצמו יצא אלא ללמד על הכלל כלו יצא, מה שביעי רשות אף כלם רשות, חוץ מלילה הראשון שהכתוב קבעו חובה, שנאמר (שמות יב, יח) בערב תאכלו מצות: **עצרת לה' אלהיך.** עצור עצמך מן המלאכה. דבר אחר כנופיא של מאכל ומשתה, לשון (שופטים יג, טו) נעצרה נא אותך:
@118 **מהחל חרמש בקמה.** משנקצר העמר שהוא ראשית הקציר:
@119 **מסת נדבת ידך.** די נדבת ידך, הכל לפי הברכה, הבא שלמי שמחה, וקדש קרואים לאכול:
@120 **והלוי:. והגר והיתום והאלמנה.** ארבעה שלי כנגד ארבעה שלך, בנך ובתך ועבדך ואמתך, אם אתה משמח את שלי, אני משמח את שלך:
@121 **וזכרת כי עבד היית** וגו' **.** על מנת כן פדיתיך, שתשמור ותעשה את החקים האלה:
@122 **באספך.** בזמן האסיף שאתה מכניס לבית פרות הקיץ. דבר אחר באספך מגרנך ומיקבך, למד שמסככין את הסכה בפסולת גורן ויקב:
@124 **והיית אך שמח.** לפי פשוטו אין זה לשון צווי אלא לשון הבטחה, ולפי תלמודו למדו מכאן לרבות לילי יום טוב האחרון לשמחה:
@125 **ולא יראה את פני ה' ריקם.** אלא הבא עולות ראיה ושלמי חגיגה:
@126 **איש כמתנת ידו.** מי שיש לו אוכלין הרבה ונכסים מרבין יביא עולות מרבות ושלמים מרבים:

@4 **ונתתה את הברכה על הר גרזים** . כתרגומו ית מברכיא את המברכים על הר גרזים כלפי הר גריזים לשון רש"י ואיננו נכון כפי פשוטו כי עדין לא צוה במברכים אלא פירושו כי אני נותן לפניכם דרך ברכה ודרך קללה וטעם "לפניכם" שתבררו לכם מהן מה שתרצו ואודיע שתהיה לכם הברכה כאשר תעשו המצות והקללה אם לא תקיימו אותן וזה כאשר אמר עוד (להלן ל טו) ראה נתתי לפניך היום את החיים ואת הטוב ואת המות ואת הרע וגו' ואחר כן אמר בכאן שיתנו הברכה הזאת אשר הוא אומר להם על הר גריזים והקללה על הר עיבל והנה היא נתונה בפה וכן ונתן אותם על ראש השעיר (ויקרא טז כא) כדברי ר"א והנה אמר בכאן בדרך האזהרה שיתנו את הברכה על הר גריזים לברך את העם אם ישמעו אל מצות ה' והקללה על הר עיבל לאמר ארור אשר לא ישמע אל המצות ויסור מן הדרך אשר צוה ה' והיה אפשר שיתנו כל השבטים הברכה וכולם הקללה או שיאמרו הלוים הכל או איש אחד משמיע לכולם ואחרי כן שב לבאר שם (להלן כז יב-יד) ואלה יעמדו לברך את העם על הר גריזים ואלה יעמדו על הקללה ואמר וענו הלוים ופירש כל הענין כי בכאן מפני אזהרתו אשר אמר ראה אנכי נותן וגו' הזכיר מקצת המצוה וחזר לבאר אותה במקומה ויתכן שהיה הר גריזים לדרום שהוא הימין והר עיבל מצפון שנאמר (ירמיהו א יד) מצפון תפתח הרעה
@7 **ושמרתם לעשות את כל החוקים ואת המשפטים** . גם בכאן יזהיר על החוקים ועל המשפטים קודם שאר המצות ויזכיר תחלה המשפט בע"ז ומשמשיה כאשר פירשתי בסדר ואתחנן (לעיל ד ג) ואחרי כן יזכיר משפטים רבים בנביא השקר ומסית ועיר הנדחת ויזכיר בחוקים תחלה הקרבנות במקדש ואח"כ איסור אכילת כל תועבה ושאר המצות
@11 **לא תעשון כן לה' אלהיכם** . להקטיר לשמים בכל מקום כי אם במקום אשר יבחר דבר אחר ונתצתם את מזבחותם ואבדתם את שמם לא תעשון כן אזהרה למוחק את השם ולנותץ אבן אחת מן המזבח או מן העזרה אמר רבי ישמעאל וכי תעלה על דעתך שישראל נותצין המזבחות אלא שלא יעשו כמעשיהם ויגרמו עונותיכם למקדש אבותיכם ליחרב לשון רש"י ודברי רבי ישמעאל סמך של אגדה הם אבל הכתוב כדעת רבותינו אזהרה למוחק את השם ומפורש במסכת מכות (כב) והא איכא מוחק את השם דלקי ואזהרתיה מהכא לא תעשון כן לה' אלהיכם ולשון ספרי (ראה ז) מנין לנותץ אבן אחת וכו' רבי ישמעאל אומר מנין למוחק אות אחת מן השם שעובר בלא תעשה שנאמר ואבדתם את שמם לא תעשון כן רבן גמליאל ברבי אומר וכי תעלה על דעתך וכו' ודברי רבי ישמעאל אינם במחלוקת אבל הם ביאור כי מוחק את השם כנותץ אבן מן המזבח ואם כן יהיה פירוש הכתוב ונתצתם את מזבחותם ואבדתם את שמם מן המקום ההוא ולא תעשון כן לה' אלהיכם לנתוץ את מזבחו ולאבד את שמו אבל תנו כבוד לשמו ולמזבחו ואל המקום אשר יבחר בו לשום שם מזבח לשמו תדרשו ותביאו עולותיכם לפניו
@12 **וטעם לשכנו תדרשו** . שתלכו לו מארץ מרחקים ותשאלו אנה דרך בית השם ותאמרו איש אל רעהו לכו ונעלה אל הר ה' אל בית אלהי יעקב (ישעיהו ב ג) כלשון ציון ישאלו דרך הנה פניהם (ירמיהו נ ה) ובספרי (ראה ח) תדרשו דרוש על פי הנביא יכול תמתין עד שיאמר לך נביא ת"ל לשכנו תדרשו ובאת שמה דרוש ומצא ואח"כ יאמר לך נביא וכן אתה מוצא בדוד וכו' ועל דרך האמת לשכנו תדרשו לכבודו תדרשו ובאת שמה לראות את פני האדון ה' אלהי ישראל וממנו אמרו חכמים "שכינה"
@13 **מעשרתיכם** . מעשר בהמה ומעשר שני לאכול לפנים מן המחיצה ואת תרומת ידכם אלו הבכורים שנאמר בהם (להלן כו ד) ולקח הכהן הטנא מידך לשון רש"י מדברי רבותינו (ספרי יב) ועל דרך הפשט יזכיר הכתוב העולות והזבחים שחייב לאוכלן שם במחיצה לפני ה' והזכיר גם כן שיביא שם המעשר והתרומה שיתן אותם לכהנים וללוים משרתי המקדש וישמחו גם הם עמכם ועם בתיכם כענין שנאמר (מלאכי ג י) הביאו את כל המעשר אל בית האוצר ויהי טרף בביתי ובחנוני נא בזאת אמר השם צבאות אם לא אפתח לכם את ארובות השמים והריקותי לכם ברכה עד בלי די וכן יסדו בבית שני בתרומה ובתרומת המעשר שיביאום למקדש שנאמר (נחמיה י לח) ואת ראשית עריסותינו ותרומותינו ופרי כל עץ תירוש ויצהר נביא לכהנים אל לשכות בית אלהינו ונאמר (שם פסוק לט) לבית אלהינו אל הלשכות לבית האוצר וטעם "תרומת ידכם" מפני שהתרומה לא נתנה בה התורה שיעור אבל היא כאשר תרים ידו וכן מה שאמר (פסוק יז) לא תוכל לאכול בשעריך יזהיר על הישראלי שלא יאכל בשעריו המעשר והבכורות והנדרים והתרומה וחזר והפריש ביניהם (בפסוק יח) כי אם לפני ה' אלהיך תאכלנו אתה ובנך ובתך הנאכל לכם והלוי אשר בשעריך יאכל שם בשעריך הראוי אליו כמו שנאמר בהם (במדבר יח לא) ואכלתם אותו בכל מקום ויקצר הכתוב בדברים המפורשים במקום אחר ואני סובר בפשוטו של מקרא זה כי "תרומת ידכם" מה שירים אדם לה' מכספו ומזהבו לעשות אותו קרבן עולה או זבח והזכיר בקרבן שלשת מינין הנדרים אשר הם הרי עלי קרבן שור או כשב או עז והנדבה אשר יאמר בשור ושה הרי זה עולה ואביא אותה למקדש והתרומה אשר ירים מכל אשר לו כסף או זהב או שהביא בהמתו חולין לעזרה ויאמר לכהנים הרי זו מידי לשם והוא מלשון כל מרים תרומת כסף ונחשת הביאו את תרומת ה' (שמות לה כד) וכן כל תרומת הקדשים אשר ירימו בני ישראל לה' (במדבר יח יט) קרבנות הם וכך אמר בשקלים (שמות ל יג) מחצית השקל בשקל הקדש וגו' תרומה לה' והם לקרבנות (מגילה כט) כי כל מה שירים אדם לה' מכל אשר לו בין לקרבנות בין לבדק הבית כענין ויקחו לי תרומה (שם כה ב) בין לכהנים משרתי ה' הכל יקרא תרומה כענין שכתוב במכס (במדבר לא כט) ונתת לאלעזר הכהן תרומת ה' והיו חולין גמורין בידו וכן ואשקלה להם את הכסף ואת הזהב ואת הכלים תרומת בית אלהינו ההרימו המלך ויועציו (עזרא ח כה) ולא אמר הכתוב "תרומותיכם" שלא נטעה בתרומת הכהנים אבל אמר "תרומת ידכם" מה שתרימו ברצונכם מן הבא בידכם והנה כל הנזכרים בכאן חייבים במחיצה כי פירוש מעשרותיכם מעשר בהמה ומעשר שני הנאכלים לפני השם כי מעשר ראשון מעשר הלוים ומעשר עני להם הוא
@15 **לא תעשון ככל אשר אנחנו עשים פה היום** . אמר רבי אברהם בדרך הפשט כי פירשו בו בעבור שהיו נוסעין ממסע אל מסע ויקריב עולה במסע שירצה ויש מי שיתן בכור צאנו ויש מי שלא יתן כי המצוה תלויה בארץ ואין זאת דעתי רק טעמו שלא היו כולם יראי השם ובעבור שאמר "אנחנו" כי מצות רבות בעולות תלויות בארץ זה לשונו ואינו נכון שאין מדרך הפרשה שידבר בתוכחות ויאמר להם עתה שאינם עושים מצות השם ואיש כל הישר בעיניו יעשה ואיך יאמר משה רבינו אנחנו עושים בעבירות חלילה אבל היה ראוי שיאמר לא תעשו ככל אשר עשיתם עד היום איש כל הישר בעיניו ומה טעם לכלול עם העבירות המצות התלויות בארץ אבל פירוש הכתוב כי ישראל נצטוו במדבר לזבוח כל בקרם וצאנם שלמים לפני המשכן (ויקרא יז ג-ו) אבל באיזה מקום שיהיה המשכן יעשה אותם ואם לא ירצה לאכול שור ושה לא יתחייב להביא קרבן כלל וגם כן אינו חייב להביא בכורות ולא מעשר בהמה ומעשר שני והנה לא יביא בחיוב למשכן כלל ואפילו ברגלים לא נתחייב לבא שם וכן אחרי זריקת הדם והקטר החלב בשלמים יאכל אותם במדבר בכל מקום שירצה כי לא נתן בהם הכתוב מחיצה אבל אוכלים אותם במחנה וחוץ למחנה והנה אין להם בכל ענין הקרבנות חובה רק איש כל הישר בעיניו יעשה על כן צוה בכאן כי אחרי המנוחה והנחלה לא יעשו כן אבל יבואו בחובה למקום ידוע ומיוחד נבחר מהשם ויביאו שם הזבחים והמעשרות והבכורות ויאכלום שם במחיצה לפני השם ומה שאמרו רבותינו (ספרי טז) בדבר הנידר והנדב שקרב בבמה ושאין נידר ונדב שאינו קרב בבמה מדרש מיתור המקרא כמו שהוא מפורש בפרק בתרא דזבחים (קיז)
@27 **כי ירחיב ה' אלהיך את גבלך** . אין טעם הרחבה זאת כאותה שיאמר (להלן יט ח ט) ואם ירחיב ה' אלהיך את גבולך וגו' ויספת לך עוד שלש ערים על השלש האלה שאם כן לא היה בשר תאוה מותר בבואם לארץ אבל שם (להלן יט א) נאמר כי יכרית ה' אלהיך את הגוים אשר ה' אלהיך נותן לך את ארצם והם שבעה הגוים שיזכיר בכל מקום ואז נבדיל שלש ערים וכן עשה יהושע (יהושע כ) ואח"כ אמר כי ירחיב ה' אלהיך את גבולך כאשר נשבע לאבותיך וזה ירמוז לעשרה עממין שנתנו לאברהם אבל כאן אמר "כאשר דבר לך" והם הגוים האלה אשר ה' אלהיך נותן לך את ארצם כי מיד לאחר שכבשו וחלקו הותר להם בשר תאוה ואין טעם "כי ירחק ממך המקום" שיהיה מותר בהרחקת המקום בלבד שאם כן יהיו אסורים יושבי ירושלים בבשר תאוה אבל עם כל ישראל ידבר ויאמר להם כי כאשר ירחיב השם את גבולכם ולא תהיו כולכם יושבים סביב למשכן כאשר אתם היום במדבר יהיה לכם בשר החולין מותר כי א"א שתלכו כולכם ממקום רחוק אל המקום אשר יבחר ה' ותזבחו זבחים שלמים כל מה שתאכלו
@28 **וטעם וזבחת וגו' כאשר צויתיך** . על דעת רבותינו (חולין כח) כאשר צויתיך על פה מהלכה למשה מסיני מלמד שנצטוה משה על הושט ועל הקנה ועל רוב אחד בעוף ועל רוב שנים בבהמה ודע כי שחיטה בלשון הקדש הוא הכרת סימני הצואר ואל תחוש בעבור שאמר וישחטם במדבר (במדבר יד טז) כי היא מליצה שזבח אותם כצאן והנה צוה בקרבנות "ושחט" "ושחטו" שהוא בסימני הצואר והנה מתחלה צוה שיהיה כל מה שהם אוכלים שלמים והם שחוטים כמשפט הקרבנות ועתה כשבא להתיר בשר החולין אמר וזבחת מבקרך ומצאנך כאשר צויתיך בהיותם קרבנות ותאכל אותם חולין בכל תאות נפשך לומר שיתירם חולין בכל מקום ובלבד שיהיו זבוחין כאשר צוה מתחלה בהיותם כולם קרבנות וזהו פשוטו של מקרא זה על הנכון ושמא רבותינו נתכונו בזה כשאמרו בספרי (ראה לט) כאשר צויתיך מה קדשים בשחיטה אף חולין בשחיטה והנה מצות השחיטה מפורשת בכאן ומבוארת מדברי רבותינו בקבלה
@29 **אך כאשר יאכל את הצבי ואת האיל כן תאכלנו** . הוא כמו שיפרש הטמא והטהור יחדו כי מפני שצוה במדבר שלא יאכלו בקר וצאן רק בזבחי שלמים ומוזהר בהם כי הנפש אשר תאכל בשר מזבח השלמים אשר לה' וטומאתו עליו ונכרתה אמר בכאן שיאכל בכל אות נפשו בחולין ושיאכלנו עם הטמא בקערה אחת כאשר הם אוכלין במדבר הצבי והאיל שאינו קרב על המזבח ואין הטעם ב"כצבי וכאיל" שיאכל חלב החולין כאשר יאכל חלב הצבי והאיל כי לא יזכיר רק האיכות כענין שאתם אוכלין הצבי והאיל תאכלו הבשר אשר תזבחו בכל מקום ולא אמר כל אשר יאכל בצבי ובאיל יאכל בו ולכך יפרש בכל מקום (להלן טו כב) הטמא והטהור יחדו (יאכלנו) כצבי וכאיל ולא אמר בשום מקום "יאכלנו כצבי וכאיל" בלבד כדי שלא יהא גם החלב בכלל וטעם "אך" אזהרה מפני כי מתחלה היה אסור לאכול רק השלמים השחוטין במשכן ועתה כשהתיר לשחוט ולאכול בשעריך ובכל אות נפשך יהיה במשמע שיאכל אפילו חולין וגם קדשים כאשר בראשונה שיקריבם שם בבמה ועל כן אמר והזהיר אך כאשר יאכל את הצבי ואת האיל כן תאכלנו שלא תקריב ממנו לא חלב ולא דם ולא תנהג בהם דרך קדשים ולא תזהיר מהם הטמאים כלל והוצרך להזכיר (בפסוק טז) רק הדם לא תאכלו מפני טעמים רבים כי מתחלה אמר באיסור הדם (ויקרא יז יא) ואני נתתיו לכם על המזבח לכפר על נפשותיכם והיה במשמע הזה שהדם שאינו מכפר בבהמה לא יאסר על כן הוצרך לאוסרו בביאור אבל בחלב לא הזכיר כן באיסורו ואין כל הקרב מן האימורין אסור ולא כל שאינו קרב מותר כאשר כתבתי במקומו (שם ג ט) ועוד כי כיון שצוה בכאן שנשחוט והזהיר שנאכל באיכות הצבי והאיל היה במשמע שנכסה הדם כאשר צונו בצבי והאיל (שם יז יג) ועל כל פנים הוצרך להתיר שנשפוך הדם כמים בלא כסוי וזה טעם "על הארץ" לא "בארץ" שיכסנו בעפר וכיון שהוצרך להזכיר היתר הדם הקדים לבאר איסורו ועוד נתירא הכתוב שלא ידונו בדם בעבור כי במדבר בעת שהיו כל בקרם וצאנם שלמים היה הבשר אסור עד שיזרוק הדם על המזבח כי כן הדין בקרבנות והנה הדם בהם מעכב אכילת הבשר וצוה מן הצבי והאיל בעבור שאינם קרבים שנכסה את דמם בעפר וכן מן העוף בעבור שאין העוף קרב לשלמים וא"כ היה מחוייב בבקר ובצאן של בשר תאוה שנכסה אותו או שנאכלנו עם הבשר בנחירה ולא יראה על פני השדה כי ראוי היה שיהא מותר לאכלו בפני עצמו ממה שישפכנו על הארץ שלא יזבחו את זבחיהם לשעירים אשר הם זונים אחריהם על כן אמר שיזבח הבקר והצאן ולא יאכל הדם עם הבשר בנחירה או באבר מן החי וישפוך הדם על הארץ ולא יחוש לו אבל לא יאכלנו לא בפני עצמו ולא עם הבשר ומן הטעם הזה הוצרך להזכיר כן פעם אחרת בבכור בעל מום (להלן טו כג) מפני שהיה הדם מתחילה למזבח והוצרך עתה לומר כשהוא בעל מום שלא ינהגו קדושה בדמו וגם לא היתר אבל ישפכנו כמים ולא יאכלנו והנראה בעיני בטעם הענין הזה כי מתחלה בהיותם במדבר ילל ישימון ושעירים ירקדו שם והיו כולם יוצאי מצרים הרגילים בהם אסר להראות הדם על פני השדה ולזבוח כלל רק לפני משכן ה' להרחיק אותם מן החטא ההוא אבל בבואם לארץ והוצרך להתיר בשר תאוה מפני ריחוק המקום לא חשש אם ישפך בביתם דם הבקר והצאן על הארץ אבל בדם החיה ועוף אשר יצוד בשדה וביער והמנהג לשחטם שם ולהביאם שחוטין אל הבית השאיר המצוה כאשר היתה לכסות דמם בעפר שלא יקריבנו לשעירים ומדרש רבותינו (ספרי מב) ב"רק חזק לבלתי אכל הדם" ו"לא תאכלנו למען ייטב לך" (פסוק כה) מדרש יפה ונאות ללשון הכתוב שהיו להוטין אחריו מאד על כן הוצרך לכל האזהרות האלה וכל שכן שהוצרך להזכיר איסורו אע"פ שלא הזכיר איסור החלב ובאמת שדבר רבותינו זה מספיק לטעם רבוי האזהרות שהכתוב מזהיר ממנו אבל הלשון שאמר "רק חזק לבלתי אכל הדם" אינו מתישב לי בכל זה כי מה חוזק ואומץ יש בהזהר מן הדם והראוי שיאמר לחומרו "השמר לך לבלתי אכול הדם" ומצינו לשון חוזק במצות שאמר הקב"ה ליהושע (יהושע א ז) רק חזק ואמץ מאד לשמור לעשות ככל התורה אשר צוך משה עבדי וכן אמר יהושע לישראל (שם כג ו) וחזקתם מאד לשמור ולעשות את כל הכתוב בספר תורת משה וזה במצות כולן ו"לשמור" ירמוז ללא תעשה ו"לעשות" ירמוז למצות עשה אבל במצוה אחת לא נמצא כן ומה צורך לחיזוק בשב ואל תעשה ממצות לא תעשה אחת אבל נראה לי כי הזכיר בה חיזוק מפני הענין אשר ממנו דבקו בדם במצרים כי היו זובחים את זבחיהם לשעירים תמיד כמו שכתוב (ויקרא יז ז) ולא יזבחו עוד את זבחיהם לשעירים אשר הם זונים אחריהם וכתיב (להלן לב יז) יזבחו לשדים לא אלוה והיתה העבודה ההיא באכילה מן הדם כי היו מקבצים הדם לשדים והם אוכלים עליו וממנו כאלו הם קרואים לשדים לאכול על שולחן השדים ההם ומתחברים עמהם וכבר הוזכר זה בספר מורה הנבוכים (ג מו) ולא שיהיה זה עיקר טעם איסור הדם כי הכתוב מפרש טעמו כי הדם הוא הנפש כאשר בסדר אחרי מות (ויקרא יז יא) אבל מזה היו שטופים בו ורודפין אחריו מאד והנה היו מתנבאים בו ומגידים עתידות ולכך בא הכתוב והזהיר שאם ישמע מאוכלי הדם דבר עתיד ובא האות והמופת אל יפתה לבבו אבל יחזיק בתומתו ובאמונת ה' ואל יאכל מן הדם בשום ענין ואל יכסה המעשה ההוא מדבריהם לא יירא ומפניהם לא יחת כי הבל המה מעשה תעתועים הזהיר בכאן כענין המוזהר בנביא השקר מפני הטעותיו
@35 **שמר ושמעת את כל הדברים האלה** . לא הזכיר בכאן "חקים ומשפטים" או "עדותיו ומצותיו" אבל אמר "את כל הדברים" להכניס בשמירה זו גם הטוב והישר כאשר פירשתי בסדר ואתחנן (לעיל ו יח)
@37 **השמר לך פן תנקש אחריהם אחרי השמדם מפניך** . אחר שתראה שאשמידם מפניך יש לתת לב מפני מה נשתמדו אלו מפני מעשים מקולקלים שבידיהם אף אתה לא תעשה כן שלא יבאו אחרים וישמידוך לשון רש"י ואם כן יהיה זה אזהרה והתראה מלעבוד ע"ז וכן כתב איכה יעבדו לפי שלא ענש על ע"ז אלא על זבוח וקטור ונסוך והשתחואה כמו שכתוב (שמות כב יט) בלתי לה' לבדו דברים הנעשים לגבוה בא ולמדך כאן שאם דרכה של ע"ז לעבדה בדבר אחר כגון פוער לפעור וזורק אבן למרקוליס שהיא עבודתו חייב וחייב על זבוח וקטור ונסוך והשתחואה אפילו שלא כדרכה עכ"ל וזה איננו נכון כי הכתוב אומר לא תעשה כן לה' אלהיך אם כן אינה אזהרה בעבודה לאלהיהם רק שלא לעבוד השם הנכבד בעבודתם כאשר נתן הטעם כי כל תועבת ה' אשר שנא עשו לאלהיהם וגו' אבל פירוש הפרשה כי עד הנה צוה פעמים רבות כי בבואנו אל הארץ נעקור ע"ז ומשמשיה ונאבד את שמם וצוה שנעשה זה מיד כאשר אנחנו יורשים אותם מיד ועתה אמר כי כאשר יכרית ה' הגוים ההם מפנינו וישתקע שם ע"ז מן הארץ ונשב בארצם לבטח לא נחשב בלבנו הנה הכרית השם מפנינו עובדי אלהים אחרים בעבור שהיו עושים כבוד בעבודה שלמה למעשה ידי אדם עץ ואבן ואין ראוי לתת כבודו לאחר ותהלתו לפסילים כי כן אסר זבוח וקטור ונסוך והשתחואה בלתי להשם לבדו והנהוג במלכים כי המתהדר בכבודם לתת עטרה בראשו או ללבוש לבוש מלכות כהם אחת דתו להמית אם כן אעשה אני לשם הנכבד כאשר היו עושים הגוים לאלהיהם וייטב לפניו לכן הזהיר לא תעשה כן כי הדברים המתועבים לפניו היו עושים לאלהיהם ולא אסרם מפני המעשה שהיה נכבד וראוי לעשותו לפני השם לבדו רק מפני הכונה שהיתה בהם לעבוד אלהות כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם שהוא דבר מתועב לפני השם לשפוך דם נקי ואף כי להיות אכזרי על פרי בטן לא ירחמו ועל כן אמר (להלן יג א) את כל הדבר אשר אנכי מצוה אתכם וגו' להזהיר על מעשה הקרבנות ועבודת המקדש שלא תוסיף עליו ולא תגרע ממנו וזה ענין הפרשה הזאת באמת אבל רבותינו (סנהדרין ס) שלמדו מכאן לעובד ע"ז כדרכה שחייב עליה לעולם אפילו פוער עצמו לפעור מפני שהזכיר הכתוב "איכה יעבדו" ללמד כי תקרא עבודה באיכות ההוא ויהיה בכלל ולא תעבדם (שמות כ ה) אבל אם יזרוק אבן לפעור או אפילו דרך כבוד שיחבק וינשק או שיכבד וירבץ לפניו אינו חייב מיתה ועל דרך הפשט הזהיר בראש הסדר (לעיל פסוק ד) "לא תעשון כן לה' אלהיכם" לעובדו כאלהי העמים על ההרים הרמים בקרבנותיו ועתה בפרשה הזאת הזהיר "לא תעשה כן לה' אלהיך" לעבדו במקדשו בעבודות שלהם
@40 (דברים יג ב): "כי יקום בקרבך נביא או חלם חלום" - יקראנו הכתוב "נביא" על פי עצמו, שיאמר הוא "השם דיבר עמי בהקיץ ואני נביאו שלוח לכם שתעשו כן".
@40 וייתכן שירמוז הכתוב למה שהוא אמת, כי בנפשות בקצת האנשים כח נבואיי ידעו בו עתידות, לא ידע האיש מאין יבא בו, אבל יתבודד ותבא בו רוח לאמר "ככה יהיה לעתיד לבא בדבר פלוני". ויקראו לו הפילוסופים "כהין", ולא ידעו סיבת הענין, אך הדבר נתאמת לעיני רואים. אולי הנפש, בהתבודדה, תדבק בשכל הנבדל ותתכוין בו. והאיש הזה יקרא "נביא" כי מתנבא הוא, ועל כן יבוא האות והמופת אשר יאמר אליך.
@40 "ונתן אליך אות או מופת" -
@40 ענין אות, סימן על דבר שיהיה אחרי כן בדמיונו, כענין שנאמר (במדבר ב ב): "איש על דגלו באותות", כי כשיבא הנביא ויאמר "דבר פלוני עתיד להיות" לדמיון שיהיה כך, ייקרא אות, כענין שנאמר (ישעיה ז יד): "לכן יתן אדני הוא לכם אות", שהאל עימנו, משם בן אשת הנביא. והמלה נגזרת מן (דברים לג ב): "אתה".
@40 והמופת ייאמר על דבר מחודש שיעשה לפנינו בשנוי טבעו של עולם, כענין שנאמר (דברי הימים ב לב לא): "לדרוש המופת אשר היה בארץ", (יואל ג ג): "ונתתי מופתים בשמים ובארץ דם ואש". והיא מלה מקוצרת מן "מופלאת", כמו (דברי הימים א יב לח): "שרית ישראל". וישאילהו הלשון לדבר שהוא חוץ מן המנהג, כמו שנאמר (יחזקאל כד כד): "והיה יחזקאל לכם למופת", ואמר (יחזקאל כד כז): "ותדבר ולא תאלם עוד והיית להם למופת", כי מעשיו פלא בעיני הרואים, כדרך (איכה א ט): "ותרד פלאים".
@40 וכן (דניאל ג לב): "אתיא ותמהיא... אתוהי כמה רברבין ותמהוהי כמה תקיפין", האותות והמופתים, כי הפלא והתימה ענין אחד.
@40 והיו ביציאת מצרים אותות, והם הדברים שיאמר להם מתחלה (שמות ח יט): "למחר יהיה האות הזה", והיו שם מופתים, שיעשו בחידוש בלי שיקדימו להודיע בו.
@40 וכן (ישעיה לח כב): "מה אות כי אעלה בית ה'", שיקדים להודיעו, ואמר באות ההוא בעצמו (דברי הימים ב לב לא): "לדרוש המופת אשר היה בארץ", לדעת החידוש ההוא איך נתחדש אצלם.
@40 וכן המטה אשר נהפך לנחש קראו (שמות ד יז): "אות" כאשר הודיע בו לבני ישראל, וקראו (שמות ד כא): "מופת" כאשר עשאו לפני פרעה לחידוש.
@40 וכן (ישעיה כ ג): "כאשר הלך עבדי ישעיהו ערום ויחף שלש שנים אות ומופת על מצרים ועל כוש", כי היה בדבר אות מגיד על מה שיאתה, ופלא במנהג שילך הנביא ככה.
@40 אם כן, "ונתן אליך אות או מופת" פירושו, שיאמר "אני הנביא השלוח אליכם שתעבדו עבודה זרה פלונית, וזה לכם האות, כי למחר יבא הארבה החסיל והגזם, או יתן להם מופת, שישליך לפניהם מטה ויהיה לתנין.
@40 ובספרי אמר: "אות הוא מופת ומופת הוא אות, אלא שדברה תורה בשתי לשונות". אולי כונתם לומר, שאין חלוק בין שניהם ואין הפרש בדינם, ודי היה להזכיר האחד, אלא שרצתה התורה להפליג בענין לומר כל אות ואות שיתן אליך, מכל אותות שבעולם.
@40 והאיש הזה שיקרא עצמו "נביא" ויצוה לעבוד עבודה זרה, על דרך הפשט נביא הע"ז הוא שיאמר "צלם פעור שלחני אליכם שהוא האלהים וצוה שתעבדוהו בכך וכך", והוא שאמר בו הכתוב עוד (דברים יח כ): "ואשר ידבר בשם אלהים אחרים ומת", כי כל מתנבא בשם אלהים אחרים לעבוד אותם יתנבא כי הם לו לאלהיו, והזכירו שם עם נביאי השקר.
@40 אבל העולה בזה מדברי רבותינו (סנהדרין צ א), כי זה הנביא הנזכר בכאן מתנבא בשם ה', יאמר "השם הנכבד שלחני שתעבדו לפעור כי היה השותף עמו במעשה בראשית, או שהוא גדול מכל האלהים לפניו ורוצה שיעבדו אליו". והם ז"ל הזכירו, כי אפילו יאמר שיעבדו לע"ז אפילו שעה אחת בלבד, כגון שיאמרו "עבדו לפעור היום הזה בלבד ותצליחו בדבר פלוני כי כן הרצון לפני השם הנכבד", הוא חייב מיתה, וגם זה הוא כפשוטו של מקרא.
@40 והנה, צוה הכתוב, שלא נשמע למתנבא בשם ה' לעבוד עבודה זרה כלל, ולא נביט באותות ובמופתים שיעשה, והזכיר הטעם, מפני שאנחנו ידענו מיציאת מצרים, שהוא מעשה ממש, לא חיזיון ולא מראה, כי לה' הארץ, והוא המחדש והחפץ והיכול ואין אלהים מלבדו, וידענו ממעמד הר סיני, כי הוא פנים בפנים ציווה אותנו ללכת בדרך הזה, שלא נעבוד לזולתו כלל, וכבודו לאחר לא ניתן, וזה טעם (דברים יג ו): "אשר צוך ה' אלהיך". והנה, "דבר סרה על ה'", שלא ציווהו ככה מעולם, או סרה דבר על כבודו, שאין ראוי לעבוד לאל אחר.
@42 (דברים יג ד): "כי מנסה ה' אלהיכם אתכם"- לאמור כי ענין המופת אשר בא והראהו השם לזה בחלומו או בכיהונו רצון האלהים היה בו לנסותכם באהבתו.
@42 וכבר פירשתי, כי הנסיון יקרא כן מצד המנוסה.
@42 ואמר "לדעת" - שייוודע בפועל מה שהוא בכח וגלוי לפניו.
@42 והנה, מצות כל הפרשה במתנבא לעבוד עבודה זרה, אבל במתנבא בשם ה' לשנות בדברי התורה, רבותינו דרשו בו (סנהדרין צ א), שאם בא לעקור דבר אחד מן התורה, כגון שיתיר החזיר או אחת מן העריות, כמשפט הזה יעשה לו. אבל אם יתיר זה לקצת הימים להוראת שעה, כגון אליהו בהר הכרמל, אנו חייבים לשמוע אליו ולעשות ככל אשר יצונו.
@42 ונראה, שאם יתנבא בשם ה' לצוות מצוה שיחדש, כגון שהיה במקרא מגלה (מגילה יד א), שאינו חייב מיתה, אלא שאין לנו לשמוע אליו, דכתיב (ויקרא כז לד): "אלה המצות", אין נביא רשאי לחדש בהם דבר מעתה. ואולי כיון שלא נאמין לו הנה הוא נביא השקר, ומיתתו בחנק.
@43 **אחרי ה' אלהיכם תלכו** . היא מצוה שנלך אחר עצתו וממנו לבדו נדרוש כל נעלם ונשאל כל עתיד כענין ותלך לדרוש את ה' (בראשית כה כב) כי יבא אלי העם לדרוש אלהים (שמות יח טו) וכן יעשו ישראל עם הנביאים האין פה נביא לה' ונדרשה את ה' מאותו (מלכים ב ג יא) ויגד לנו ה' אלהיך את הדרך אשר בה נלך ואת הדבר אשר נעשה (ירמיהו מב ג) ובספרי אחרי ה' אלהיכם זה ענן והוא מה שפירשנו שנשמע לקול אותותיו ונלך אחרי עצתו ואותו תיראו שתאמינו כי הוא אשר בידו נפש כל חי ובידו להמית ולהחיות ופוקד עון ומשלם שכר ואת מצותיו תשמרו תורת משה
@43 "ובקולו תשמעו" - לעשות כל מה שיצוה אותנו מלבד התורה כמו שאמר שמואל (שמואל א יג יג) נסכלת לא שמרת את מצות ה' והוא מה שפירש עוד (להלן יח טו) נביא מקרבך מאחיך כמוני יקים לך ה' אלהיך אליו תשמעון ואמר (שם פסוק יט) והיה האיש אשר לא ישמע אנכי אדרש מעמו שהוא חייב מיתה בידי שמים וכמו שבא במצות הנביא הכני ופצעני בדבר ה' (מ"א כ לה לז) וכן אמרו בספרי (ראה ס) ובקולו תשמעו בקול נביאיו
@43 "ואתו תעבדו ובו תדבקון" - כבר פירשתיו (לעיל ו יג יא כב) והנה כבר נאמר (לעיל ו יג) את ה' אלהיך תירא ואותו תעבוד אבל החזירו בכאן לשלול שלא נירא מדברי הנביא מפני האות והמופת ולא נעבור על עבודת ה' בעבור דבריו כי מן ה' לבדו נירא ולא מאל אחר ולהוסיף ובקולו תשמעו
@47 **לא תאבה לו** . לא תהא תאב לו ולא תאהבנו לפי שנאמר (ויקרא יט יח) ואהבת לרעך כמוך את זה לא תאהב לשון רש"י מספרי (ראה סז) אבל בגמרא (סנהדרין סא) אמרו הא אבה ושמע חייב וכן הדבר כי אבה לשון רצון ולא אבה ה' אלהיך לשמוע אל בלעם (להלן כג ו) לא רצה לא אבה יבמי (להלן כה ז) ממה שאמר (שם) ואם לא יחפץ והנה לא תאבה לו בלב ולא תשמע אליו שתודה לו לומר כן אעשה אלך ואעבוד עבודה זרה שאמרת והוא חייב מיתה בהודאתו וכן דעת אונקלוס לא תקבל מיניה ואלו הלאוין כמו ולא תתאוה ולא תחמוד (לעיל ה יח) שאם התאוה בלב עובר בלאו הראשון ואם הוסיף לעשות כאשר חשב עובר גם בלאו השני
@47 "ולא תחוס עינך עליו" - לרחם עליו שלא יומת ולא תחמל על הקורבה הנזכרת שיש לו עמך כענין שנאמר (מלאכי ג יז) כאשר יחמול איש על בנו העובד אותו
@47 "ולא תכסה עליו" - מהעיד עליו בב"ד ובספרי (ראה סח) לא תחמול לא תלמד עליו זכות ולא תכסה אם אתה יודע לו חובה אינך רשאי לשתוק והכל טעם אחד כי הכסוי מן מכסה פשעיו (משלי כח יג) וכוסה קלון (שם יב טז) השתיקה מהגיד ואמר ולא יוספו לעשות כדבר הרע הזה כי הוא דבר מצוי יעשה תמיד לולי המשפט אבל ענין הנביא הנזכר איננו בתדירות
@53 **ודרשת וחקרת ושאלת היטב** . הדרישה והחקירה מפורשין בדברי רבותינו (סנהדרין מ) והזכיר הכתוב זה בעיר הנדחת ובעובד ע"ז ולא הזכיר כן בנביא השקר ובמסית כי הנביא מפרסם עצמו באותותיו ובמופתיו ובמסית הכתוב ידבר עם המוסת "כי הרג תהרגנו" והוא היודע ועד כמו שאמר "ולא תחמול ולא תכסה עליו" אבל בעיר הנדחת ובעובד ע"ז שהם מעשים מגיעים אלינו בשמועה הזכיר בהם דרישה וחקירה ולא הוצרך להזכיר כן בשאר חייבי מיתות כי מקל וחומר יודע הדבר ואמר בעדים זוממים (להלן יט יח) ודרשו השופטים היטב בעבור שלא יודע מי משתי הכתות יאמר האמת בלתי אחר חקירה רבה ולענין הדין כלן למדין זה מזה בגזירה שוה ומכלם יצאו לנו שבע חקירות ובדיקות
@54 **החרם אתה ואת כל אשר בה** . אותה הם אנשים הנדחים ואת כל אשר בה הנשים הנגררות אחר האנשים אבל הטף שהם קטנים בזכרים ובנקבות אין ממיתין אותן וכן אמרו בספרי חנן אומר לא יומתו אבות על בנים וגו' בעיר הנדחת הכתוב מדבר אבל בתוספתא של מסכת סנהדרין (פי"ד ה"א) נחלקו בה קטני בני אנשי עיר הנדחת שהודחו עמה אין נהרגין רבי אליעזר אומר נהרגין אמר לו רבי עקיבא מה אני מקיים ונתן לך רחמים ורחמך והרבך (פסוק יח) אם לרחם על הגדולים הרי כבר נאמר החרם אותה ואת כל אשר בה ואת בהמתה ומה אני מקיים ורחמך והרבך אלו קטנים שבתוכה וכו' והנה כל אלו המצות ביאור מה שנאמר בתורה (שמות כב יט) זובח לאלהים יחרם ועתה ביאר החרם מהו במדיחים ובעובדים
@58 **בנים אתם לה' אלהיכם** . גם זו מצוה מבוארת שאמר בתורה (ויקרא כא ה) בכהנים לא יקרחו קרחה בראשם ובבשרם לא ישרטו שרטת ועתה יבאר כי לא בעבור מעלת הכהנים בלבד שהזכיר שם שהם קדושים לאלהיהם צוה בהם זה אבל כל העדה כלם קדושים וכלכם בנים לה' אלהיכם כמו הכהנים אם כן השמרו גם אתם במצוה הזאת כמותם ועל דעת רבותינו בשניהם אינה אלא על המת ויתכן שהיתה המצוה הראשונה בכהנים לאמר שאם היה הכהן מקורח ומגודד איננו ראוי לעבודה כמו שאמר (שם פסוק ו) ולא יחללו שם אלהיהם והנה עבודתם מחוללת וכאן ביאר כי המצוה גם לישראל והוצרכו לשתיהם ורש"י כתב לפי שאתם בניו של מקום אתם ראויים להיות נאים ולא גדודים ומקורחים ואיננו נכון שאם כן תהיה המצוה גם שלא על המת ור"א אמר אחר שתדעו שאתם בנים לה' והוא אוהב אתכם יותר מן האב לבנו לא תתגודדו על כל מה שיעשה כי כל מה שיעשה לטוב הוא ואם לא תבינוהו כאשר לא יבינו הבנים הקטנים מעשה אביהם רק יסמכו עליו כי עם קדוש אתה ואינך כשאר כל הגוים על כן לא תעשה כמעשיהם ולפי דעתי כי טעם "עם קדוש" הבטחה בקיום הנפשות לפניו יתברך יאמר אחרי שאתה עם קדוש וסגלת ה' ולא ישא אלהים נפש וחשב מחשבות לבלתי ידח ממנו נדח אין ראוי לכם להתגודד ולהקרח על נפש ואפילו ימות בנוער ולא יאסור הכתוב הבכי כי הטבע יתעורר לבכות בפירוד האוהבים ונדודם אף בחיים ומכאן סמך לרבותינו (מו"ק כז) באסרם להתאבל על נפש יותר מדאי
@60 **לא תאכל כל תועבה** . הנה רצה להוסיף ביאור במאכלים האסורים ולכך אמר "לא תאכל כל תועבה" להגיד כי כל הנאסרים נתעבים לנפש הטהורה וענין כל תיעוב שנאה ומיאוס כענין כי נתעב דבר המלך (דהי"א כא ו) כל אכל תתעב נפשם (תהלים קז יח) כי המאכלים האסורים גסים יולידו עובי ואטימות בנפש כאשר הזכרתי במקומו (שמות כב ל) ועל כן אמר עוד (פסוק כ) כל עוף טהור תאכלו להגיד כי אלה אשר אסר נתעבים והשאר טהורים וראויים לנפש טהורה ובספרי אמרו רבי שמעון אומר כל עוף טהור תאכלו אלו חגבים טהורים וכל שרץ העוף (פסוק יט) אלו חגבים טמאים ויפה אמר והנה טעם הכתוב כי הזכיר לאסור כל שרץ העוף והם ההולכים על ארבע וחזר ואמר כל עוף טהור תאכלו להתיר מהם אשר לו כרעים ממעל לרגליו הארבה והסלעם והחרגול והחגב ולא הוצרך לפרש זה שכבר הוזכר (ויקרא יא כא כב) אבל הזכיר בכלל דרך קצרה כל עוף טהור תאכלו כלומר אלו הנזכרים מאכלים נתעבים ושאר העופות למיניהם למרביתם תאכלו מהם כל טהור שלא אסרתיו והנה כלל כל הנאסרים לנו שהם כלם תועבה ולא הוצרך לפרוט אחרי כן השרצים וכל הרמש כי דבר ידוע הוא שתתעב אותם נפש כל נקי דעת אבל הזכיר סימני הבהמה והחיה והדגים והעופות והנבלה להודיעך שגם הם מתועבים לנפש ולא הזכיר הטרפה שאיננה תועבה אבל נאסרה מפני הארס או החולי הממית שלא יזיק באוכליו ולרבותינו עוד מדרשים (חולין סג) למה נשנו בבהמה מפני השסועה ובעופות מפני הראה ועוד מדרש (ספרי צח קידושין נז) בכל צפור טהורה תאכלו להתיר משולחת של מצורע וזה אשר לא תאכלו מהם לאסור את השחוטה קבלו כן לרמוז ב"כל צפור טהורה" שהצפור שלא קבלה טומאה מותרת וטומאת המצורע לא תדבק בחיה שאין בעלי חיים בבהמה ובעוף מקבלים טומאה בנוגעם במת או בשרץ אבל השחוטה שראויה לקבל טומאה ידבק בה רוח הטומאה הפורחת מן המצורע ואיננה טהורה והיא בכלל תועבה כי אכילתה נתעבת
@78 **וטעם כי עם קדוש אתה לה' אלהיך** . דבק עם לא תבשל גדי בחלב אמו כי איננו מאכל נתעב אבל יאסור אותו להיותנו קדושים במאכלים או להיותנו קדושים שלא נהיה עם אכזרי לא ירחמו שנחלוב את האם ונוציא ממנה החלב שנבשל בו הבן ואף על פי שכל בשר בחלב יכנס בלאו הזה כי כל מינקת תקרא אם וכל יונק יקרא גדי והוא דרך הבישול והנה בכולם אכזריות וכתב רש"י לא תבשל גדי בחלב אמו שלשה פעמים פרט לחיה ולעופות ולבהמה טמאה והמדרש הזה הוציאו אותו (ספרי קג וחולין קיג) ממלת גדי אבל הלאו עצמו אחד לאיסור אכילה ואחד לאיסור הנאה ואחד לאיסור בישול וכן כתב הרב בסדר ואלה המשפטים (שמות כג יט)
@79 **עשר תעשר** . גם זו מצוה שיבאר כי אמר (ויקרא כז ל) וכל מעשר הארץ מזרע הארץ מפרי העץ לה' הוא קדש לה' ואמר (שם פסוק לא) ואם גאל יגאל איש ממעשרו חמשיתו יוסף עליו ואין זה מעשר הלוים כי בו נאמר (במדבר יח לא) ואכלתם אותו בכל מקום והוא חולין ומה טעם לפדיונו ועתה באר כי הוא יחייב לעשר כל תבואת זרעך שיאכל אותו הוא עצמו ובניו לפני השם למען תלמד ליראה את השם כי הכהנים והשופטים העומדים שם לפני השם מורי התורה ילמדוהו יראתו ויורוהו התורה והמצות ופירש בטעם הפדיון אשר הזכיר שם בעבור כי לפעמים יהיה המעשר הרבה כי יברכך השם והדרך יהיה רב ממנו וטוב לפדותו בכסף ולהעלות שם כסף הפדיון ולא הזכיר החומש שכבר הוזכר וטעם היוצא השדה וכל היוצא השדה כאשר אמר מזרע הארץ מפרי העץ וטעמו היוצא מן השדה ואין הכונה ב"כל תבואת זרעך" שיעשר כל התבואה מכל אשר זרע ולא כל היוצא מן השדה שנה שנה אבל טעם הכתוב שיעשר במינים המחוייבים במעשר כל תבואתו וכל היוצא בהן מן השדה יזהיר שלא יעשר מן הבא בידו מהם המקצת ויפטור לו המקצת אבל יעשר בין המדות שזרע בין הנתוסף עליהם הכל באמונה ואחר כך (פסוק כג) הזכיר המינים המחוייבים להתעשר מעשר דגנך ותירשך ויצהרך וכן יזכיר בכל מקום (לעיל יב יז) לא תוכל לאכל בשעריך מעשר דגנך ותירשך ויצהרך וגו' וכן אמר בפרשת מתנות כהונה (במדבר יח יב) כל חלב יצהר וכל חלב תירוש ודגן ראשיתם אשר יתנו לה' כי אלו בלבד הם החייבים בתרומה ובמעשרות מן התורה וכן מה שאמר הכתוב (ויקרא כז ל) וכל מעשר הארץ מזרע הארץ מפרי העץ לה' הוא לא יצוה שיעשר כל זרע הארץ וכל פרי העץ אבל טעמו כל אשר תעשר מזרע הארץ שהוא דגן ומפרי העץ שהוא תירוש ויצהר יהיה לה' וכלשון הזה כתב רש"י (שם) מזרע הארץ דגן ופרי העץ תירוש ויצהר ויקצר הכתוב שם כי איננו מקום המצוה לחייב שיעשר אבל הוא מצוה שיהיה המעשר קדש לה' עד שיפדה בתוספת חומש אבל המצוה בתרומות ומעשרות בכל מקום הן דגן תירוש ויצהר ופירוש דגן בלשון הקדש חמשת המינין הידועין בתבואה ופירוש תירוש היין החדש אשר ישיקו היקבים ויצהר השמן אשר בהן ואין מין אחר בכל הזרעין ובכל פירות האילן חייבין מן התורה כלל לא בתרומות ולא במעשרות ויש ברייתות שנויות בתורת כהנים (בחקותי פרק יב ט) ובספרי (ראה קה) לאסמכתות והן מוטעות אבל הדבר המתבאר בגמרא מן התלמוד הבבלי (ברכות לו) והירושלמי (חלה פ"ד ה"ד) ופשוטו של מקרא כך הוא שאפילו זיתים וענבים מעשר שלהם אינו מן התורה עד שיעשו תירוש ויצהר ותהיה בזה נזהר שכבר טעו בו מגדולי המחברים (עי' רמב"ם הלכות תרומות פ"ב ה"א) וטעם שנה שנה שיעשר אותו שתי שנים זו אחר זו כן קבלת רבותינו (ר"ה יב) ואחר כך (פסוק כח) פירש כי מקצה השלש שנים תוציא מעשר תבואתך של השנה ההיא ותאכילהו לעניים לומר כי השנה השלישית של מעשר עני הוא ואמר תוציא וגו' והנחת בשעריך ללמד על הביעור ושוב יבאר אותו בפרשת כי תכלה לעשר (להלן כו יב) ומדרש חכמים (בתנחומא ראה יח) בלשון עשר תעשר עשר בשביל שתתעשר עשר שלא תתחסר רמז למפרשי ימים להוציא אחד מעשרה לעמלי תורה
@87 **מקץ שבע שנים תעשה שמטה** . הנכון בעיני שיזהיר על שנת השבע עצמה שנעשה אותה שמטה בחריש ובקציר כמו שאמר (שמות כג יא) והשביעית תשמטנה ונטשתה וזה טעם "תעשה שמטה" שתשבות כדרך לעשות את יום השבת (לעיל ה טו) וקצר באסור הזריעה והזמירה שכבר הזכירם בביאור (ויקרא כה ד) אבל הוסיף לבאר כי היא שמטה לה' גם בהשמט כספים וזה טעם כי קרא שמטה לה' שהיא שבת לה' וכל המעשים ישבותו וכבר רמזתי סודה (שם שם ב) וטעם "מקץ" אמר ר"א בתחלת השנה וכן אמרו המדקדקים כלם כי הראש והסוף יקראו קצה שכל דבר יש לו שתי קצוות וכענין שכתוב מן הקצה אל הקצה (שמות כו כח) על שני קצותיו (שם כה יט) על ארבע קצותיו (שם כז ד) ואין דבריהם נכונים אצלי כי ראש שבע שנים הוא השנה הראשונה והוא הקצה שנקרא בהם ראש ואלו אמר הכתוב "מקץ השנה השביעית" היה דברם נכון ועל דעת רבותינו (ספרי קכב) "מקץ" בסוף השבע ולא ידבר הכתוב אלא בשמיטת כספים יאמר מסוף כל שבע שנים הנמנים לכם תעשו שמטה שישמוט כל בעל משה ידו ולכך אמרו (ערכין כח) שאין שביעית משמטת אלא בסופה וכן לדעתם (שם) מקץ שבע שנים במועד שנת השמטה בחג הסכות בסוף השבע אלא שהקץ הנזכר בכאן הוא מיד והקץ הנזכר שם מופלג שהרי פירש במועד שנת השמטה בחג הסכות והנה טעם שניהם "מתכלית" יאמר בכאן מתכלית שבע שנים תעשה שמטה ושם יאמר בו גם כן כאשר תכלינה שבע שנים במועד שנת השמטה תעשה הקהל ועל דרך הפשט יראה לי כי לשון הכתוב כפשוטו הוא ברור ומתוקן כי קץ הוא סוף וכן תרגומו והמספרים וכל דבר יש להן ראש וסוף וראשם וסופם בהם ותאמר בעשרות כי האחד ראש המספר והעשירי סופו אם כן "קץ שבע שנים" שנת השבע שהוא סוף המספר ההוא ובשמטת הארץ הכתוב מדבר כאשר פירשתי למעלה וטעם "מקץ" כמו כרוב אחד מקצה מזה וכרוב אחד מקצה מזה (שמות כה יט) והנה הוא כמו בקץ שבע שנים תעשה שתשבות בו וכן מקץ שבע שנים תשלחו איש את אחיו העברי אשר ימכר לך ועבדך שש שנים (ירמיהו לד יד) פירושו בשנה השביעית שהוא סוף המספר והוא דומה לכתוב שבתורה (שמות כא ב) ובשביעית יצא לחפשי חנם וכן ובשנה השביעית תשלחנו חפשי מעמך (להלן פסוק יב) כי בעבור שאמר "ועבדך שש שנים" לא הוצרך לפרש רק כי בשנת השביעית יפטר והנה על דרך הזה היה נראה כי פירוש הכתוב האחר מקץ שבע שנים במועד שנת השמטה בחג הסוכות שיהיה כמו כן בשנת הקץ בחג הסוכות בראש אותו השנה שנאסרו בה לחרוש ולזרוע שהיא שנת השמטה אבל לא נוכל לומר כן כי רבותינו (סוטה מא) קבלו וראו שהיה ההקהל בחג הסוכות של השנה השמינית היא השנה שאחר השמטה ועל כן אמרו המפרשים כי פירוש "במועד שנת השמטה" במועד השנה הראשונה של מנין השמטה וזה איננו נכון כי לא תקרא בכתוב "שנת השמטה" רק שנת השבתון השנה ההיא שהיא שמטה לה' וכן "שנת היובל" ורבותינו עצמם דקדקו בכך שאמרו (ערכין כד) מי כתיב בשנת היובל משנת היובל כתיב שנה שאחר היובל אבל כך אני אומר כי הקץ והסוף יאמרו בכתוב על אחרית כל דבר ופעמים הם בו ופעמים אחריו חוץ ממנו ומקצה אחיו (בראשית מז ב) מקצה בחוברת (שמות כו ד) ומקצתם יעמדו לפני המלך (דניאל א ה) מקצות כנפיו ועד קצות כנפיו (מלכים א ו כד) כלם אחרית בדבר המחבר ממנו והוא בתוכו קץ כל בשר בא לפני (בראשית ו יג) ובא עד קצו ואין עוזר לו (דניאל יא מה) בא הקץ (יחזקאל ז ב) קץ בא (שם פסוק ו) כלם תכלית הדבר הנזכר והוא אחריו שנקצץ ונחתך וכן הענין בלשון הסוף טוב ללכת אל בית אבל וגו' באשר הוא סוף כל האדם (קהלת ז ב) אחריו שכבר מת ספו תמו מן בלהות (תהלים עג יט) את המעשה אשר עשה האלהים מראש ועד סוף (קהלת ג יא) במעשה עצמו ובלשונם (ב"ב יג) כדי עמוד בתחילתו וכדי היקף בסופו ויהיה פירוש הכתוב מתכלית שבע שנים בחשבון שנת השמטה בחג הסוכות הבא אחר השבע תעשה הקהל ושלא יראה להם שיהיו שבע שנים למנין אחר הזכיר שיהיו השבע בזמן השמטה וכן כי אקח מועד (תהלים עה ג) זמן וכן כל המועדים זמנים והנה הקץ הזה אחרי המספר כאשר פירש "בחג הסוכות" ו"מקץ שבע שנים תעשה שמטה" מכלל המספר ולא הוצרך להאריך ולבאר זה שכבר פירש ששנת השבע היא שנת השמטה ויהיה קץ רחב בשמטת כל השנה כמו שפירשתי על דרך הפשט ויתכן לומר כי הכתוב מונה תחלת שנה מחג הסוכות כמו שאמר (שמות לד כב) וחג האסיף תקופת השנה ואמר (שם כג טז) וחג האסיף בצאת השנה וא"כ יהיה "מקץ שבע שנים" בסוף וחוץ ממנו בסמוך ואמר "במועד שנת השמטה" להיות חשבון השבע בשמטות כמו שפירשתי לא שתגיע השמטה עד החג הזה וראיתי לאחד מן המחברים שכתב מלמד שמוסיפים מחול על הקדש והשמטה היתה נוהגת עד חג הסוכות של שנה שמינית וזה דבר מוכרח בתלמוד (ר"ה יב) בראיות ברורות שאיננו אמת ואפשר לומר כי מה שאמרו רבותינו ב"מקץ שבע שנים תעשה שמטה" שאין משמטת כספים אלא בסופה שהוא מדרש מפני שלא אמר "השנה השביעית תעשה שמטה" ירמוז כי בסוף השבע תעשה שמטה יותר מן ההתחלה ורצונם בקץ הזה חוץ ממנו ויכול אדם לתבוע חובו ביום האחרון של שנת השמטה ולא תשמט עד הלילה שכך מצינו בתוספתא (שביעית ח יא) שכותבין פרוזבול ערב ר"ה של מוצאי שביעית
@89 **את הנכרי תגש** . זו מצות עשה לשון רש"י מספרי (ראה קל) ופירושו מצות עשה באחיך הנכרי תגוש ולא אחיך ולאו שבא מכלל עשה עשה ולפי ששנינו שם (ספרי קכט) לא יגוש ליתן עליו לא תעשה חזרו ושנו את הנכרי תגוש זו מצות עשה לומר שעובר עליו בעשה ולא תעשה וכך אמרו שם (ספרי תצא קכט) לנכרי תשיך (להלן כג כא) מצות עשה ולאחיך לא תשיך זו מצות לא תעשה והוא כמו שפירשנו מצות עשה באחיך וכך פירש שם רש"י לא שיהיה מצוה להלוות לנכרי ברבית כלל וכן מוכח בגמרא בפרק איזהו נשך (ב"מ ע) והרב רבי משה (הל' מלוה ולוה פ"א ה"ב ושם פ"ה ה"א) עשאן שתיהן מצות ממש לנגוש את הנכרי ולהלוותו ברבית טעה בלשון הזה השנוי בספרי ושם הוא מורגל במקומות רבים כל עוף טהור תאכלו מצות עשה כל שרץ העוף מצות לא תעשה וכן הזכירו בספרא (שמיני פרשה ג א) ובספרי (ראה צו) זאת הבהמה אשר תאכלו מצות עשה ודבר ברור הוא
@97 **כי לא יחדל אביון מקרב הארץ** . מפרשים אמרו שלא יחדל האביון מקרב הארץ באחד מכל הזמנים כי לעולם יהיה אביון בארץ שגלוי היה לפניו שלא יעשו מה שאמר להם כי לא יהיה בך אביון אם שמוע תשמע בקול ה' אלהיך לשמור לעשות את כל המצוה ואינו נכון לדעתי כי התורה תרמוז במה שעתיד להיות אבל לא יתנבא עליהם בפירוש שלא יקיימו התורה ויצוה המצוה לעולם וחלילה רק בדרך אזהרה יזכיר הדבר והנכון שיאמר שלא יחדל אביון שיהיה נמנע ולא ימצא עוד לעולם והזכיר זה בעבור שהבטיח שלא יהיה בהם אביון בשמרם כל המצוה אמר אבל ידעתי כי לא יהיו כל הדורות כל ימי עולם כלם שומרים כל המצוה עד שלא נצטרך כלל לצוות על האביון כי אולי בקצת הימים ימצא אביון ואני מצוך עליו אם ימצא ואמר "מקרב הארץ" לרמוז על כל הישוב כי ההבטחה שלא יהיה בנו אביון בארץ אשר ה' אלהינו נותן לנו נחלה אם נקיים שם כל המצות ועתה אמר כי יתכן שימצא אביון באחד מן הזמנים ובאחד מן המקומות אשר תשב בה כי טעם "בארצך" כטעם בכל מושבותיכם (במדבר לה כט) בארץ ובחוצה לארץ וטעם ולאביונך בארצך כאומר לאחיך העני ולכל אביוני ארצך כי בעבור שהמצוה לישראל יזכיר אחיך ויצטרך לפרש אחיך וכל אביוני ארצך לצוות על כלל ישראל ומדרשו (ספרי קמב) להקדים הקודם
@110 **שמור את חדש האביב** . מצות הרגלים מבוארת כי כבר הזכירה (ויקרא כג במדבר כח כט) והנה בתורת כהנים הזכיר בה ענין הקרבנות והקרבתם אשה לה' וכאן לא יזכירם כלל אבל יזהיר את ישראל לעלות בהם אל המקום אשר יבחר ולשמוח לפניו כי כאשר צוה שיביא מעשר שני לפני ה' וכן הבכור ויאכלם שם במקום אשר יבחר ה' הוסיף לבאר כי עוד חייבין שיבואו כלם לפני השם ויחגו לפניו בשלשה רגלים ולשמוח בשלמים שיקריבו לפניו ולא הזכיר זמני חג המצות והסוכות באי זה יום יהיה אך הזכיר חדשיהם דרך קצרה שכבר הזכיר הכל שם
@111 **וטעם וזבחת פסח לה' אלהיך צאן ובקר** . על דרך הפשט כמו שור שה כשבים (לעיל יד ד) ראובן שמעון לוי (שמות א ב) ואמר וזבחת פסח לה' אלהיך וצאן ובקר לכך לא אמר וזבחת פסח לה' אלהיך מן הצאן ומן הבקר כאשר יאמר בכל מקום מן הבקר ומן הצאן תקריבו את קרבנכם (ויקרא א ב) ואם מן הצאן קרבנו (שם פסוק י) אם מן הבקר הוא מקריב (שם ג א) אבל יצוה בכאן בפסח והוא השה שהזכיר כבר וצאן ובקר אילים ועזים ובני בקר לחוג חגיגה ביום הזה כאשר יצוה בשבועות ובסוכות שיאמר (פסוק י) ועשית חג שבעות לה' אלהיך מסת נדבת ידך שיביא בקר וצאן לשלמים כאשר תשיג ידו וכן אמר בסוכות (פסוק טו) שבעת ימים תחג לה' אלהיך וגו' ובסוף כלל את שלשתם ודומה לזה בראשון בארבעה עשר יום לחדש יהיה לכם הפסח חג שבועות ימים מצות יאכל (יחזקאל מה כא) ופירש בחג שבעת ימים וכן מצינו בפסח יאשיהו שאמר (דהי"ב לה ז) צאן כבשים ובני עזים הכל לפסחים ובקר שלשת אלפים ואחר כן אמר (שם פסוק יג) ויבשלו הפסח באש כמשפט והקדשים בשלו בסירות ובדודים ובצלחות ויריצו לכל בני העם הנה פירש כי כבשים ובני עזים הכל לפסחים לא עזים עצמן ולא בקר כדכתיב (שמות יב ה) שה תמים זכר בן שנה יהיה לכם מן הכבשים ומן העזים ופירש כי הבקר אשר הזכיר היו שלשת אלפים והיו קדשים אשר בסירות להריץ לפני העם לאכול לשבעה כענין החגיגה שקבלו רבותינו (פסחים ע) ואונקלוס עשה צאן דבק עם הפסח ולא יתקשר הוי"ו יפה במלת ובקר ועוד כי אין כל הצאן כשר לפסחים והנכון מה שאמרנו ובאר בכאן דברים רבים כי הזכיר במצה שתהיה לחם עני להגיד כי צוה לזכור שיצאו בחפזון והיא עני זכר כי היו במצרים בלחם צר ומים לחץ והנה תרמוז לשני דברים וכן אמרו הא לחמא עניא די אכלו אבהתנא בארעא דמצרים או יאמר שתהיה עוד עשויה כלחם עני ולא שתהיה מצה עשירה כמו שהזכירו רבותינו (פסחים לו) ובאר במצות השאור שלא יראה בכל גבולך כי בתחלה אמר (שמות יב יט) לא ימצא בבתיכם
@113 **וטעם אשר תזבח בערב ביום הראשון** . שלא ילין לבקר מן הבשר שעשית אותו זבח בערב יום הראשון שבשבעת הימים הנזכרים והוא הלילה כמו שהזכיר (פסוק א) הוציאך ה' אלהיך ממצרים לילה כי לא הזכיר בפרשה הזאת יום ארבעה עשר ושחיטת הפסח כלל אבל הזכיר עשיית הפסח בלילה כלומר אכילתו ואכילת המצה עליו והטעם כי זביחת הפסח והקרבתו ביום ארבעה עשר היא מצות הקרבנות והזכיר אותה בתורת הקרבנות (ויקרא כג ה) ולא החזירה כאן כאשר לא החזיר מצות שאר הקרבנות וגם בשלשת הרגלים לא הזכיר כאן שנקריב בהם אשה אבל על אכילת הפסח והמצה הזכיר כאן לישראל וכן שם תזבח את הפסח בערב כבוא השמש (פסוק ו) שם תעשה זבח הפסח בערב בשקוע החמה כי בלילה יאכל ואמר לבאר זה (פסוק ז) ובשלת ואכלת במקום אשר יבחר ה' ופנית בבקר וכבר פירשתי זה בפרשת החדש הזה לכם ראש חדשים (שמות יב ו) ויתכן עוד שנפרש ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר מן הבשר אשר זבחת בערב והוא הערב הקודם לבקר שהוא ביום ארבעה עשר ואמר שם תזבח את הפסח בערב ו כבא השמש מועד צאתך ממצרים ובשלת ואכלת אותו והזכיר סתם "ובשלת" כי כבר פירש שם (שם שם ח ט) צלי אש ולא בשל מבושל במים אם כן ובשלת באש כמשפט
@117 **וביום השביעי עצרת לה' אלהיך לא תעשה מלאכה** . ולא הזכיר היום הראשון באיסור המלאכה וכן לא הזכיר בחג השבועות איסור מלאכת עבודה ולא בסוכות ולא הזכיר מצות הלולב וכן לא הזכיר כאן יום הזכרון ובעשור לחדש והטעם כאשר פירשתי (בפסוק א) כי לא בא עתה רק להזכיר הראיה והשמחה שחייבין כל ישראל ללכת בשלש הרגלים האלה אל המקום אשר יבחר ה' ולחוג שם איש כמתנת ידו כברכת השם אשר נתן לו לשמוח לפניו להודות על כל הטובה אשר גמלנו כרחמיו וכרוב חסדיו והוסיף וביום השביעי עצרת וטעמו ששת ימים תאכל מצות והשביעי עוד עליהם עצרת והטעם שתהיו עוד נעצרים לפניו לאכול המצות ובעבור שאמר עצרת היא ויהיה במשמע להיות נעצר על אכילת המצות בלבד כימים אשר לפניו הוצרך להזהיר שלא תעשה מלאכה וכן אמר בשמיני של חג הסוכות בפרשת המועדות שבתורת כהנים (ויקרא כג לו) שבעת ימים תקריבו אשה לה' ביום השמיני מקרא קדש והקרבתם אשה לה' עצרת היא כל מלאכת עבודה לא תעשו לומר שהוא נעצר על הימים הראשונים בהקרבת האשה והוא אסור עוד בעשיית מלאכת עבודה ועל דרך האמת עצרת היא כנסת ישראל ובא ללמדנו סוד היום אבל איננו שוה לעצרת של שמיני כי השמיני רגל בפני עצמו והקרבן של כנסת ישראל ואיננו כקרבנות של שבעת הימים אבל שביעי של פסח הוא מכלל הרגל ועצרת כי לפעמים תמנה שמינית ולפעמים תהיה בכלל והנה היא כשבת שיש בה זכור ושמור כבוד יום וכבוד לילה והקרבן בשביעי מכלל הרגל ועל כן אמר כאן עצרת לה' אלהיך לא תעשה מלאכה ושם אמר והקרבתם אשה לה' עצרת היא כי האשה עצרת ולכך היא סעודה קטנה והמשכיל יבין ולא הזכיר כאן השמיני של חג שכבר הוזכר ואיננו חייב שנעלה בו לרגל פעם אחרת
@118 **מהחל חרמש בקמה** . טעמו מהחל לכם חרמש בקמה כי כבר הזכיר מתי נתחיל להניף חרמש בקמה בעומר שהיא ראשית קצירנו ומדרשו (ספרי קפו) ללמד על העומר שלא תהא קצירתו אלא בחרמש
@120 **במקום אשר יבחר ה' לשכן שמו שם** . וכן אמר (פסוק טז) שלוש פעמים בשנה יראה כל זכורך וגו' במקום אשר יבחר ולא ידעתי אם לומר כי לאחר שיבנה בית המקדש לא נאסף להקריב קרבנות הרגלים אלא במקום ההוא אשר יבחר ה' כטעם שיאמר (פסוק ה) לא תוכל לזבוח את הפסח באחד שעריך או שיבאר כאן שלא יתחייבו לעלות לרגל עד אשר יבחר השם מקום לשכנו שם
@121 **וזכרת כי עבד היית במצרים** . אמר ר"א שהוא דבק עם ועבדך ואמתך והנכון שהוא כפשוטו שתשמור החקים האלה אשר צוך האדון הפודך מבית עבדים וכן נזכיר בקדוש היום הזה זכר ליציאת מצרים ואמר החקים האלה בחג השבועות בעבור שלא נתפרש בתורה טעם מספר שבעה השבועות ומספר החמשים יום והוא לבדו העצרת וכבר הזכרתי סודם (ויקרא כג טו) צוה בתורה עד האלהים יבא דבר שניהם (שמות כב ח) ונתן בפלילים (שם כא כב) אם כן מצוה שיהיו לישראל פלילים וביאר בכאן שישימו השופטים בכל עריהם כאשר יתן להם השם את הארץ כי בחוצה לארץ אינם חייבים למנות להם ב"ד אבל כאשר יצעק המעוות יעמדו עליו הראויים לשפוט ובמשפטיהם ישפטוהו או יעלה לארץ בזמנה ושם ישפטוהו במקום המשפט והוסיף בכאן שוטרים והם שיהיו נוגשים בדבר המשפט ולפי זה אין ישראל שבחוצה לארץ מצווים למנות להם דיינין בעיירות וכן כתב הרב ר' משה (הל' סנהדרין פ"א ה"ב) אבל במסכת מכות (ז) שנו והיו אלה לכם לחוקת משפט לדורותיכם בכל מושבותיכם מלמד שסנהדרין נוהגת בארץ ובחוצה לארץ אם כן למה נאמר שופטים ושוטרים תתן לך בכל שעריך אלא בארץ אתה מושיב בכל פלך ופלך ובכל עיר ועיר בחוצה לארץ אתה מושיב בכל פלך ופלך ואי אתה מושיב בכל עיר ועיר ונראה מזה שחייבין למנות סנהדרין בחוצה לארץ ולא בכל עיר ועיר כארץ ישראל אלא פלכים פלכים אם כן המצוה הזאת נוהגת בכל זמן בדיני ממונות ובדברים הנדונין בחוצה לארץ אבל בזמן הזה לאחר שבטלה הסמיכה כיון שכל המשפטים בטלים מן התורה דכתיב לפניהם ולא לפני הדיוטות ואנן הדיוטות אנן ואין דיינין בחוצה לארץ אלא תקנה דשליחותיהו עבדינן (גיטין פח) אין אנו חייבים במצות מינוי שופטים מן התורה כלל
